// Original Kō explanations and examples. Reference coverage lives in coverage.json.
const defaultReadings={'一人':'ひとり','二人':'ふたり','一日':'いちにち','二日':'ふつか','一晩':'ひとばん','三日':'みっか','一歩':'いっぽ','一夜':'いちや','一目':'ひとめ','忘る':'わする','十五分':'じゅうごふん'};
const p=(id,purpose,formation,register,restrictions,mistake,examples)=>({id,purpose,formation:[formation],register,restrictions,mistake,...(id==='n1-126'?{aliases:['に堪える','に堪えない']}:{}),examples:examples.map(([text,translation,note,readings={}])=>({text,translation,note,readings:{...Object.fromEntries(Object.entries(defaultReadings).filter(([surface])=>text.replace(/[\[\]]/g,'').includes(surface))),...(id==='n1-172'?{'術':'すべ'}:{}),...readings}}))});
export default [
p('n1-001','Choose a course deliberately despite a reason to avoid it.','敢えて + action; 敢えて + negative','neutral','Highlights a conscious choice against expectations.','With a negative, it means deliberately refraining, not trying harder.',[
['今日は[敢えて]遠回りして帰る。','Today I am deliberately taking the long way home.','A less convenient route is a choice.'],['理由は[敢えて]聞かなかった。','I chose not to ask the reason.','Restraint can also be deliberate.'],['会議で[敢えて]反対意見を述べた。','I deliberately voiced a dissenting opinion at the meeting.','The speaker accepts social friction.']]),
p('n1-002','Keep a position or limit in place despite other considerations.','あくまでも + statement','neutral','Often stresses a principle or that something is only a proposal.','It does not automatically mean forever; the limit depends on context.',[
['これは[あくまでも]私の提案です。','This is only my proposal.','Limits the authority of the statement.'],['彼は[あくまでも]自分の説を守った。','He maintained his theory to the end.','An unwavering position.'],['参加は[あくまでも]自由です。','Participation is entirely voluntary.','The voluntary principle remains in force.']]),
p('n1-003','Report an outcome that confirms an earlier expectation.','案の定 + result','neutral','Common with an unwelcome but predictable result.','Use for a confirmed result, rather than a future guess.',[
['傘を忘れたら、[案の定]雨が降った。','I forgot my umbrella and, sure enough, it rained.','The feared result occurs.'],['[案の定]、休日の駐車場は満車だった。','As expected, the parking lot was full on the holiday.','Prior experience supports the expectation.'],['急いで書いたので、[案の定]誤字があった。','I wrote in a hurry and, predictably, there were typos.','The cause made the result foreseeable.']]),
p('n1-004','Arrange something before the time when it is needed.','あらかじめ + preparation','neutral/formal','Usually accompanies notice, checking, or preparation.','It implies anticipation, rather than merely an earlier event.',[
['人数を[あらかじめ]知らせてください。','Please tell us the number of people in advance.','An advance notice request.'],['材料は[あらかじめ]切っておいた。','I cut up the ingredients beforehand.','Preparation eases later work.'],['変更の可能性を[あらかじめ]説明した。','I explained the possibility of changes in advance.','The explanation precedes a potential change.']]),
p('n1-005','Present something as the indispensable basis for something else.','N + あっての + N','emphatic','The first noun sustains the second.','This is dependence, not a simple sequence of two events.',[
['お客様[あっての]商売です。','Our business depends on our customers.','Customers make the business possible.'],['健康[あっての]仕事だ。','Good health is the foundation for work.','Well-being comes before work.'],['仲間[あっての]優勝だった。','Our teammates made that victory possible.','Acknowledges essential support.']]),
p('n1-006','Emphasize that a particular reason makes an action possible or meaningful.','Conditional ば + こそ','formal/emphatic','Often gives a positive motivation for an apparently harsh action.','Keep the conditional form: 思えばこそ, not 思うばこそ.',[
['君を信じれ[ばこそ]任せたのだ。','I entrusted it to you precisely because I trust you.','Trust motivates delegation.'],['大切に思え[ばこそ]厳しく注意する。','I warn you firmly precisely because I care.','Explains a seemingly negative action.'],['苦労があれ[ばこそ]成功がうれしい。','Success feels wonderful precisely because of the struggle.','Difficulty gives the result value.']]),
p('n1-007','Say that if a crucial condition fails, everything ends there.','Conditional ば / たら + それまでだ','neutral','The condition makes further effort or argument pointless.','It is stronger than merely saying something will be difficult.',[
['秘密が漏れれ[ばそれまでだ]。','If the secret gets out, it is all over.','A single failure ends the plan.'],['信用を失っ[たらそれまでだ]。','Once we lose trust, that is the end of it.','Trust is an essential condition.'],['嘘だと言われれ[ばそれまでだ]が、私は見た。','You could simply dismiss it as a lie, but I saw it.','Acknowledges an argument that could end the discussion.']]),
p('n1-008','State a firm written prohibition or an unacceptable quality.','V dictionary + べからず; V dictionary + べからざる + N','literary/formal','する may become すべからず; typical of signs and solemn judgments.','べからざる modifies a noun; べからず closes a prohibition.',[
['芝生に入る[べからず]。','Do not enter the lawn.','A terse written prohibition.'],['これは許す[べからざる]行為だ。','This is an unacceptable act.','The form modifies 行為.'],['この教訓を忘る[べからず]。','Never forget this lesson.','A deliberately literary maxim.']]),
p('n1-009','Connect an intended goal to the action taken to achieve it.','V dictionary + べく; する → するべく / すべく','formal/written','Typically the same agent pursues the goal and performs the action.','Use for intention, not an accidental cause.',[
['真相を確かめる[べく]現地へ向かった。','I headed to the site to establish the truth.','An investigation has a deliberate goal.'],['負担を減らす[べく]制度を改めた。','We revised the system to reduce the burden.','The reform serves a purpose.'],['地域に貢献す[べく]基金を設立した。','We established a fund to contribute to the community.','The shortened すべく is formal.']]),
p('n1-010','Judge an outcome to be beyond realistic possibility.','V dictionary + べくもない','formal/written','Often with 望む, 比べる, or 知る.','This is impossibility, not a recommendation against acting.',[
['この予算では完成を望む[べくもない]。','With this budget, completion is out of the question.','Resources rule out success.'],['当時の技術とは比べる[べくもない]。','It cannot possibly be compared with the technology of that era.','The gap makes comparison unreasonable.'],['他人の心の奥までは知る[べくもない]。','There is no way to know the deepest part of another person’s heart.','Marks a limit to knowledge.']]),
p('n1-011','Describe a result as a natural consequence of the conditions.','V dictionary + べくして + same V, usually past','formal','Often judges a failure or success retrospectively.','The repeated verb links inevitability to the actual result.',[
['準備不足で、負ける[べくして]負けた。','Unprepared, we lost as was only to be expected.','The outcome follows from poor preparation.'],['安全を軽視した結果、起こる[べくして]起きた事故だ。','Ignoring safety made this an accident waiting to happen.','A preventable but foreseeable result.'],['練習を重ねた彼は、勝つ[べくして]勝った。','After so much practice, he deservedly won.','Can also describe an earned success.']]),
p('n1-012','Describe a visible quality resembling a particular stage or condition.','Established noun/stem + びる / びた / びて','neutral/literary','Used in established words such as 大人びる and 古びる.','Do not attach びる freely to any noun.',[
['妹は急に大人[びて]見えた。','My younger sister suddenly looked grown-up.','Appearance suggests greater maturity.'],['古[びた]机を磨いた。','I polished the timeworn desk.','びた modifies a noun.'],['子供たちは大人[びた]口調で話した。','The children spoke in a grown-up tone.','The quality is apparent in their speech.']]),
p('n1-013','Evaluate the manner or extent of someone’s action.','Vます stem + ぶり / っぷり; N + ぶり','neutral; っぷり colloquial','This entry concerns manner, not the elapsed-time use of ぶり.','Use the stem: 働きぶり, not 働くぶり.',[
['彼の働き[ぶり]には感心する。','I admire the way he works.','Evaluates sustained performance.'],['見事な食べ[っぷり]だね。','You certainly eat with gusto.','A lively colloquial evaluation.'],['落ち着いた話し[ぶり]が印象に残った。','Her calm way of speaking stayed with me.','Describes observable manner.']]),
p('n1-014','Present someone as putting on an attitude or identity.','N / adjective stem + ぶる; ぶった + N','often critical','Common with 偉い, 大人, 専門家.','Unlike びる, ぶる often suggests deliberate pretence.',[
['彼は専門家[ぶって]説明を始めた。','He began explaining as if he were an expert.','The speaker doubts the claimed authority.'],['偉[ぶる]人は苦手だ。','I find people who put on airs hard to deal with.','The attitude is criticized.'],['弟は大人[ぶった]ことを言う。','My little brother says things to sound grown-up.','ぶった modifies what he says.']]),
p('n1-015','Emphasize that even a minimal thought or possibility is extreme.','V dictionary + だに; Vます stem / N + だにしない','literary','Common fixed combinations include 想像するだに and 微動だにしない.','Do not substitute it casually for every everyday さえ.',[
['被害を想像する[だに]恐ろしい。','Even imagining the damage is frightening.','The thought alone is enough.'],['彼は爆音にも微動[だにしなかった]。','He did not stir even at the deafening noise.','An emphatic negative minimum.'],['計画が失敗するとは夢[だに]思わなかった。','I never even dreamed the plan would fail.','A literary expression of total surprise.']]),
p('n1-016','List several examples in a loose, often complaining way.','N / plain clause + だの … + だの','colloquial','The list is illustrative, not exhaustive.','The tone can sound dismissive; avoid it in a careful neutral inventory.',[
['机には本[だの]紙[だの]が積んである。','Books, papers, and all sorts of things are piled on the desk.','A disordered assortment.'],['暑い[だの]疲れた[だの]と文句ばかりだ。','It is nothing but complaints about being hot or tired.','Lists complaints with irritation.'],['週末は掃除[だの]洗濯[だの]で終わった。','The weekend disappeared into cleaning, laundry, and the like.','The chores are representative.']]),
p('n1-017','Express regret or reproach about an unrealized expectation.','Plain form + だろうに','emotional','Often follows a hypothetical condition; context supplies the contrast.','The ending suggests disappointment, rather than neutral prediction.',[
['早く相談すれば助けられた[だろうに]。','If you had asked sooner, I could have helped.','Regret about a missed chance.'],['あの服なら暖かい[だろうに]、なぜ着ないの。','That coat would be warm; why don’t you wear it?','An expectation contrasts with someone’s choice.'],['一言あれば安心した[だろうに]。','A single word would have put me at ease.','The reassuring word never came.']]),
p('n1-018','Assert that a condition does not change the main judgment.','N / な-adjective stem + であれ / であろうと','formal','Often includes たとえ or a question word.','For verbs use a suitable ようと form, not dictionary + であれ.',[
['初心者[であれ]規則は守ってください。','Even beginners must follow the rules.','Status does not excuse the duty.'],['誰[であろうと]無断では入れない。','No one may enter without permission, whoever they are.','An unrestricted condition.'],['不便[であれ]この家を残したい。','Even if it is inconvenient, I want to preserve this house.','Accepts a disadvantage.']]),
p('n1-019','Make the same statement for two alternative conditions.','N + であれ + N + であれ','formal','Pairs parallel categories; neither changes the conclusion.','It does not mean that both alternatives happen simultaneously.',[
['晴れ[であれ]雨[であれ]式は行う。','The ceremony will take place whether it is sunny or rainy.','Weather does not alter the plan.'],['学生[であれ]社会人[であれ]応募できる。','Students and working adults alike may apply.','Both categories are eligible.'],['賛成[であれ]反対[であれ]理由を聞きたい。','Whether you agree or disagree, I want to hear your reasons.','Requests a reason in either case.']]),
p('n1-020','Attribute two roles or qualities to the same thing.','N / な-adjective stem + でもあり … + でもある','neutral/formal','The two descriptions are both applicable.','This is additive, not a choice between alternatives.',[
['彼は医師[でもあり]作家[でもある]。','He is both a doctor and a writer.','Two professional roles.'],['この決断は勇敢[でもあり]危険[でもある]。','This decision is both courageous and risky.','Positive and negative evaluations coexist.'],['あの店は書店[でもあり]喫茶店[でもある]。','That place is both a bookstore and a café.','Two functions share one space.']]),
p('n1-021','Reject a description emphatically.','N / な-adjective stem + でも何でもない; い-adjective stem + くも何ともない','colloquial/emphatic','Often dismisses an assumption or downplays something.','Remove い before くも: 怖くも, not 怖いくも.',[
['私は専門家[でも何でもない]。','I am no expert at all.','Rejects an assumed identity.'],['その話は怖[くも何ともない]。','That story is not frightening in the slightest.','Dismisses an evaluation.'],['これは特別[でも何でもない]日常の道具だ。','This is an ordinary tool, nothing special at all.','Emphatically ordinary.']]),
p('n1-022','Use a rhetorical question to insist on the right description.','N + でなくてなんだろう','emphatic/literary','The speaker strongly affirms the noun.','It is not a genuine request for another answer.',[
['これが奇跡[でなくてなんだろう]。','If this is not a miracle, what is?','Strongly calls it a miracle.'],['黙って支える姿は愛[でなくてなんだろう]。','What is that quiet support if not love?','The rhetorical question affirms love.'],['約束を破るなら裏切り[でなくてなんだろう]。','If you break your promise, what is that if not betrayal?','An emphatic moral judgment.']]),
p('n1-023','Present a tentative conclusion for the reader to consider.','Plain clause + のではあるまいか; N + ではあるまいか','formal/written','A rhetorical conjecture, often in argument.','Despite まい, this commonly proposes a positive possibility.',[
['原因は温度差[ではあるまいか]。','Could the cause be the temperature difference?','A cautiously proposed cause.'],['説明が足りないの[ではあるまいか]。','Might the explanation be insufficient?','Invites reconsideration.'],['今こそ制度を変える時[ではあるまいか]。','Is this not the time to change the system?','A restrained rhetorical recommendation.']]),
p('n1-024','Reject behavior as unsuitable by invoking what someone is not.','N + ではあるまいし','often reproachful','Usually precedes criticism or advice.','The noun describes an inappropriate comparison, not the actual identity.',[
['子供[ではあるまいし]、自分で片付けて。','You are not a child; tidy up after yourself.','Rebukes dependence.'],['機械[ではあるまいし]、休みも必要だ。','We are not machines; we need rest too.','Rejects an unreasonable expectation.'],['初対面[ではあるまいし]、そんなに緊張しないで。','It is not our first meeting; don’t be so nervous.','Uses a rejected situation to reassure.']]),
p('n1-025','Warn that a minor response or description will not be enough.','N + では済まない','neutral','The matter requires greater consequences, action, or cost.','The noun is the inadequate outcome, not the action required next.',[
['この損害は謝罪だけ[では済まない]。','An apology alone will not settle this damage.','Further responsibility remains.'],['修理代は一万円[では済まない]。','The repairs will cost more than ten thousand yen.','The amount is insufficient.'],['今回は注意[では済まない]だろう。','This time it probably will not end with a warning.','More serious consequences are likely.']]),
p('n1-026','Emphasize that no available method can change a situation.','どうにも + negative / ならない','neutral','Conveys helplessness or inability to resolve a problem.','Keep a negative conclusion; it is not a simple question about how.',[
['鍵がなくては[どうにも]入れ[ない]。','Without the key, there is no way to get in.','An obstacle blocks all methods.'],['眠くて[どうにも]集中でき[ない]。','I am so sleepy I cannot concentrate at all.','A strong inability.'],['このままでは[どうにも]ならない。','Nothing can be done if things stay like this.','The situation needs to change.']]),
p('n1-027','Depict an action occurring immediately when another happens.','V dictionary / た + が早いか + past event','written/narrative','Usually observed events, often with the same actor.','Avoid using it to issue an instruction or state a future intention.',[
['ベルが鳴る[が早いか]、猫は逃げ出した。','The instant the bell rang, the cat ran away.','Almost simultaneous events.'],['彼は椅子に座る[が早いか]眠ってしまった。','He fell asleep the instant he sat down.','A very rapid change.'],['扉が開く[が早いか]、客がなだれ込んだ。','As soon as the doors opened, customers poured in.','A narrative description of immediate movement.']]),
p('n1-028','Judge two related people or things as equally characteristic.','N1 + が / も … なら、N2 + も … だ','often critical','Parallel evaluations usually reinforce one another.','Both halves need a matching evaluative relationship.',[
['親[が]親[なら]、子[も]子[だ]。','Like parent, like child.','Often criticizes similar behavior.'],['店員[も]不親切[なら]、店長[も]不親切[だ]。','The manager is just as unhelpful as the staff.','Two related targets share a fault.'],['兄[も]頑固[なら]、弟[も]頑固[だ]。','The younger brother is just as stubborn as the older one.','Parallel character judgments.']]),
p('n1-029','Describe something as unpleasantly suggestive of a quality.','Established N / stem + がましい','often critical','Used in words such as 押し付けがましい and 恩着せがましい.','This suffix is not freely productive with every noun.',[
['押し付け[がましい]助言は避けたい。','I want to avoid giving overbearing advice.','Advice feels imposed.'],['彼の言い方は恩着せ[がましい]。','The way he speaks makes you feel indebted.','A favor is used to claim gratitude.'],['言い訳[がましい]説明になってしまった。','My explanation ended up sounding like an excuse.','An unwanted impression.']]),
p('n1-030','Combine a main outing or activity with a secondary purpose.','N / Vます stem + がてら','neutral','Often with movement or a convenient opportunity.','The two activities need a practical connection.',[
['散歩[がてら]郵便局に寄った。','I stopped at the post office while out for a walk.','One outing serves two purposes.'],['花見[がてら]川沿いを歩こう。','Let’s walk along the river and enjoy the blossoms.','The scenery accompanies the walk.'],['見学[がてら]新しい工房を訪ねた。','I visited the new workshop to look around as well.','A visit includes observation.']]),
p('n1-031','Make a literary comparison with another image or entity.','N + のごとき / のごとく / のごとし','literary','ごとき modifies nouns; ごとく modifies predicates; ごとし closes a statement.','ごとき can sound belittling when applied to a person.',[
['矢の[ごとく]時が過ぎる。','Time passes like an arrow.','An adverbial comparison.'],['夢の[ごとき]一夜だった。','It was a dreamlike night.','A noun-modifying form.'],['静かな湖は鏡の[ごとし]。','The still lake is like a mirror.','A deliberately literary ending.']]),
p('n1-032','Include an entire unit or group in one action.','N + ぐるみ','neutral','Common with 家族, 町, 組織, or 身.','It means including the whole unit, not simply near it.',[
['家族[ぐるみ]で付き合っている。','Our families socialize together.','The relationship includes whole families.'],['町[ぐるみ]で祭りを支えている。','The whole town supports the festival.','Community-wide involvement.'],['組織[ぐるみ]の隠蔽が発覚した。','An organization-wide cover-up came to light.','Responsibility extends beyond one individual.']]),
p('n1-033','Describe being forced by events into an unwanted action.','V dictionary + 羽目になる','neutral/colloquial','The result is burdensome or regrettable.','Avoid for a straightforward welcome opportunity.',[
['電車を逃して歩く[羽目になった]。','I missed the train and ended up having to walk.','An unwelcome consequence.'],['鍵をなくし、窓から入る[羽目になった]。','I lost my key and had to climb in through the window.','Circumstances force an awkward solution.'],['不備が見つかり、全部やり直す[羽目になった]。','Errors were found, and we had to redo everything.','The burden was not planned.']]),
p('n1-034','Downplay an event as not serious enough to justify a reaction.','V dictionary + ほどのことではない','neutral','Often reassures someone about apology, surprise, or worry.','The verb names an excessive reaction, not the event itself.',[
['少し遅れただけで、謝る[ほどのことではない]。','You are only a little late; it is not worth apologizing over.','Downplays a small delay.'],['この傷は心配する[ほどのことではない]。','This scratch is not serious enough to worry about.','Offers reassurance.'],['偶然会っただけで、驚く[ほどのことではない]。','We merely met by chance; it is nothing to be surprised about.','Restrains a reaction.']]),
p('n1-035','Choose the less bad of two unwelcome alternatives.','Plain form + ほうがましだ','neutral/colloquial','The preferred option is still not ideal.','It is weaker praise than ほうがいい.',[
['嘘をつくより黙る[ほうがましだ]。','Staying silent is better than lying.','Neither option is presented as ideal.'],['あの部屋より廊下の[ほうがましだ]。','The corridor is better than that room.','A deliberately low standard.'],['徹夜するより少し寝た[ほうがましだ]。','A little sleep is better than staying up all night.','A less harmful choice.']]),
p('n1-036','Describe unrestricted action, availability, or neglect.','Vます stem + 放題','neutral; sometimes critical','食べ放題 is a service; 荒れ放題 describes an unchecked state.','Do not assume every use means permission.',[
['この店は野菜が食べ[放題]だ。','At this restaurant you can eat as many vegetables as you like.','A service offers unrestricted quantity.'],['庭の草は伸び[放題]になっている。','The grass in the garden has been left to grow unchecked.','No one controls the growth.'],['好き勝手に言い[放題]言われた。','They said whatever they liked about me.','An uncontrolled action is resented.']]),
p('n1-037','Make a decision depend on a particular factor.','N + いかんだ; N（の）+ いかんでは / いかんによっては','formal','The noun names a determining condition or its contents.','いかん is not the question word いかに.',[
['開催するかは天候[いかんだ]。','Whether we hold it depends on the weather.','The factor determines the decision.'],['検査結果[いかんでは]再検査が必要になる。','Depending on the results, another examination may be needed.','One outcome may trigger further action.'],['返答の[いかんによっては]契約を見直す。','Depending on the reply, we may reconsider the contract.','The response controls a later decision.']]),
p('n1-038','Remove a factor from consideration in a formal rule.','N（の）+ いかんにかかわらず / いかんによらず / いかんを問わず','formal','Often found in eligibility rules and official statements.','Unlike いかんでは, this says the factor does not matter.',[
['理由の[いかんにかかわらず]返金はできません。','We cannot issue refunds, whatever the reason.','A formal blanket condition.'],['経験の[いかんによらず]研修を受ける。','Everyone receives training regardless of experience.','Experience does not exempt anyone.'],['成否の[いかんを問わず]結果を報告する。','Report the result whether it succeeds or fails.','Either outcome requires reporting.']]),
p('n1-039','Refer formally to any kind of person, thing, or circumstance.','いかなる + N + も / negative / condition','formal','Usually broadens the statement to all possible cases.','It modifies a noun; use いかに for degree or manner.',[
['[いかなる]理由でも暴力は認めない。','Violence is unacceptable for any reason.','No reason is exempt.'],['[いかなる]困難にも立ち向かう。','We will face any difficulty.','An unrestricted range of obstacles.'],['[いかなる]変更も事前に通知する。','We will give advance notice of any change.','The rule covers every kind of change.']]),
p('n1-040','Emphasize degree or ask formally about a method.','いかに + predicate; いかに … か; いかに … ても','formal','Often occurs in reflection, explanation, or concession.','Match the ending to the meaning: か asks degree; ても concedes it.',[
['準備が[いかに]大切[か]を学んだ。','I learned how important preparation is.','An embedded degree expression.'],['[いかに]急いでも間に合わない。','However much we hurry, we will not make it.','The result holds despite the degree.'],['資源を[いかに]守るかが課題だ。','The challenge is how to protect resources.','A formal question of method.']]),
p('n1-041','Say that appearance strongly fits an expected image.','いかにも + description; いかにも … そうだ','neutral','Can also affirm agreement emphatically.','An appearance is not proof; そうだ preserves that distinction.',[
['この机は[いかにも]丈夫そうだ。','This desk looks very sturdy.','Appearance supports an impression.'],['彼は[いかにも]職人らしい手をしている。','He has hands that look every bit a craftsman’s.','A characteristic appearance.'],['[いかにも]、それは私の筆跡です。','Indeed, that is my handwriting.','An emphatic affirmation.']]),
p('n1-042','Keep a conclusion in place whichever possibility is true.','いずれにしても / いずれにしろ / いずれにせよ + conclusion','neutral/formal','Usually follows alternatives or uncertainty.','It does not decide which alternative is correct.',[
['電車でもバスでも、[いずれにしても]乗り換えが必要だ。','Whether by train or bus, we need to change.','Both routes share a requirement.'],['[いずれにしろ]今日は決められない。','Either way, we cannot decide today.','The uncertainty does not change the limit.'],['成功するかは不明だが、[いずれにせよ]試す価値はある。','Success is uncertain, but it is worth trying either way.','Maintains a judgment despite uncertainty.']]),
p('n1-043','Give something the impression of an excessive or odd quality.','N + じみた / じみている','often critical','Common with 子供, 冗談, and 夢.','じみた modifies a noun; do not treat it as a standalone noun.',[
['子供[じみた]争いはやめよう。','Let’s stop this childish quarrel.','An age-inappropriate quality.'],['冗談[じみた]値段に驚いた。','I was shocked by the absurdly high price.','The price seems almost a joke.'],['夢[じみた]計画でも実現したい。','I want to realize the plan, however fanciful it seems.','The idea resembles a dream.']]),
p('n1-044','Frame a formal choice between whether something is true or not.','Plain clause + か否か; N / な-adjective + であるか否か','formal/written','Often embedded in a decision or investigation.','否か is read いなか here, not ひか.',[
['参加する[か否か]を明日知らせる。','I will say tomorrow whether I will participate.','A pending binary decision.'],['本物である[か否か]を調べる。','We will investigate whether it is genuine.','A formal verification.'],['必要[か否か]、まず話し合おう。','First, let’s discuss whether it is necessary.','A question placed before deliberation.']]),
p('n1-045','Reveal that an outcome contradicts an initial expectation.','Plain clause + かと思いきや','narrative','The first clause sets up what seemed likely.','The second clause must overturn or sharply redirect that expectation.',[
['閉店した[かと思いきや]、改装中だった。','I thought it had closed, but it was being renovated.','The initial interpretation is corrected.'],['猫が眠った[かと思いきや]、急に走り出した。','Just when I thought the cat was asleep, it suddenly ran off.','An unexpected action.'],['楽に勝つ[かと思いきや]、接戦になった。','We expected an easy win, but it became a close match.','The actual course differs from expectations.']]),
p('n1-046','Express a strong personal feeling at the present situation.','い-adjective / な-adjective + な + 限りだ','formal/emotional','Most natural with feelings such as うれしい, 残念, 心細い.','Do not use it indiscriminately with objective physical properties.',[
['温かい言葉を頂き、うれしい[限りです]。','Your kind words make me extremely happy.','A formal expression of gratitude.'],['展示が中止とは残念な[限りだ]。','It is deeply disappointing that the exhibition is canceled.','A personal emotional response.'],['誰にも相談できず、心細い[限りだ]。','With nobody to consult, I feel terribly alone.','Expresses a present feeling strongly.']]),
p('n1-047','Say that effort failed to produce its hoped-for result.','Vた + 甲斐もなく; N + の甲斐もなく','neutral','The preceding effort is real but unsuccessful.','Do not use it for success; that takes 甲斐があって.',[
['徹夜した[甲斐もなく]、原稿は不採用だった。','Despite working all night, my manuscript was rejected.','Effort does not secure acceptance.'],['治療の[甲斐もなく]、木は枯れてしまった。','Despite treatment, the tree died.','Care proves unsuccessful.'],['探し回った[甲斐もなく]、鍵は見つからなかった。','Despite searching everywhere, I did not find the key.','An extended search ends without success.']]),
p('n1-048','State that evidence or conditions leave an outcome possible.','Plain clause + 可能性がある; N + の可能性がある','neutral/formal','Works for welcome and unwelcome outcomes.','Possibility is not a guarantee or a numerical probability.',[
['午後は雪が降る[可能性がある]。','It may snow this afternoon.','A possible future event.'],['記録に誤りがある[可能性がある]。','There may be an error in the records.','A possibility requiring a check.'],['新しい用途の[可能性がある]。','There is potential for new uses.','The noun describes a possible development.']]),
p('n1-049','Emphasize that an amount is surprisingly large.','Quantity + からある / からする / からの + N','emphatic','からする commonly concerns price; からの often modifies people or an amount.','This is an approximate lower bound, not the ordinary starting-point から.',[
['二十キロ[からある]荷物を運んだ。','I carried baggage weighing a good twenty kilos.','Highlights a substantial weight.'],['この椅子は十万円[からする]。','This chair costs upward of a hundred thousand yen.','A striking price.'],['会場には千人[からの]観客が集まった。','A good thousand spectators gathered at the venue.','Emphasizes the crowd size.']]),
p('n1-050','Apply a conclusion across two contrasting degrees.','い-adjective stem + かれ + opposite stem + かれ','formal/fixed','Common pairs include 遅かれ早かれ and 多かれ少なかれ.','Use established pairs rather than inventing arbitrary combinations.',[
['遅[かれ]早[かれ]結論は出る。','A conclusion will emerge sooner or later.','The timing does not change the outcome.'],['誰もが多[かれ]少な[かれ]不安を抱える。','Everyone has some anxiety, to a greater or lesser extent.','A shared condition varies in degree.'],['良[かれ]悪し[かれ]経験は残る。','For better or worse, the experience stays with you.','Either evaluation leaves an effect.']]),
p('n1-051','Politely combine a visit with another purpose.','Action noun + かたがた + movement verb','formal/polite','Common with お礼, ご挨拶, お見舞い, and ご報告.','Typically accompanies a visit, not two unrelated abstract actions.',[
['お礼[かたがた]ご挨拶に伺います。','I will visit to greet you and express my thanks.','A polite dual-purpose visit.'],['ご報告[かたがた]研究室を訪ねた。','I visited the laboratory and took the opportunity to report back.','Reporting accompanies the visit.'],['お見舞い[かたがた]近況を知らせに行った。','I visited to wish her well and share my news.','Concern and conversation share one visit.']]),
p('n1-052','Describe a continuing main activity alongside another pursuit.','V dictionary / N + の + かたわら','written','The activities coexist over a period, rather than at one exact instant.','Do not confuse this with がてら for a convenient outing.',[
['会社で働く[かたわら]小説を書いている。','I write novels while also working at a company.','Two ongoing pursuits.'],['農業の[かたわら]地域の歴史を調べた。','Alongside farming, she researched local history.','A sustained secondary activity.'],['大学で教える[かたわら]翻訳も続けている。','He continues translating alongside university teaching.','Professional roles coexist.']]),
p('n1-053','Locate a situation in the past or deny any past occurrence.','かつて + past; かつて … ない','neutral/written','Often refers to an earlier era or unprecedented scale.','Do not use it as a normal future-time expression.',[
['ここには[かつて]大きな池があった。','There used to be a large pond here.','A place has changed.'],['[かつて]ない規模の調査が始まった。','A survey on an unprecedented scale has begun.','No earlier instance matches it.'],['彼とは[かつて]同じ工房で働いていた。','I once worked in the same workshop as him.','A former shared situation.']]),
p('n1-054','Point out an undesirable tendency with some restraint.','V dictionary / N + の + 嫌いがある','formal','Usually criticizes a recurring inclination.','嫌い here is きらい, but it does not mean disliking the action.',[
['彼は結論を急ぐ[嫌いがある]。','He has a tendency to rush to conclusions.','A recurring weakness.'],['この議論は抽象的になりすぎる[嫌いがある]。','This discussion tends to become too abstract.','A cautious criticism.'],['若さを過信する[嫌いがある]。','There is a tendency to be overconfident about youth.','An unwelcome inclination.']]),
p('n1-055','Say that a process or list has no practical end.','Vたら / ば + 切りがない; N + は切りがない','neutral','Often explains why one must stop or limit something.','切り means an endpoint here, not a physical cut.',[
['欠点を数えたら[切りがない]。','There is no end to counting the flaws.','The list could continue indefinitely.'],['心配し始めると[切りがない]。','Once you start worrying, there is no end to it.','A process can feed itself.'],['上を見れば[切りがない]。','There is always someone above you.','A fixed warning against endless comparison.']]),
p('n1-056','Identify someone or something as outstanding within a group.','Group noun + きっての + N','neutral/emphatic','Often praises a specialist or prominent characteristic.','The first noun defines the group, not the quality.',[
['彼女は町[きっての]料理人だ。','She is the town’s foremost cook.','Ranks someone within a community.'],['兄は家族[きっての]読書家だ。','My older brother is the biggest reader in the family.','A family member stands out.'],['あそこは県内[きっての]名所だ。','That is one of the prefecture’s outstanding sights.','Prominence within an area.']]),
p('n1-057','Describe a quality as reaching an extreme.','な-adjective stem + 極まる / 極まりない','formal/emphatic','Common with 危険, 失礼, and 無責任.','Do not add な before 極まりない.',[
['危険[極まる]運転を目撃した。','I witnessed extremely dangerous driving.','An extreme negative evaluation.'],['説明もなく中止とは失礼[極まりない]。','Canceling without explanation is utterly rude.','Strong criticism.'],['無責任[極まりない]発言だった。','It was a completely irresponsible remark.','An emphatic judgment.']]),
p('n1-058','Concede one quality while firmly denying another.','N + こそあれ … negative; degree + こそあれ','formal','Often contrasts a minor problem with absence of a serious one.','The second clause must supply the contrasting judgment.',[
['不満[こそあれ]、辞めるつもりはない。','I do have complaints, but I have no intention of quitting.','Concedes dissatisfaction, denies departure.'],['違い[こそあれ]、優劣はない。','There are differences, but neither is superior.','Difference does not imply hierarchy.'],['多少の傷[こそあれ]、機能に問題はない。','It has some scratches, but it works perfectly well.','Cosmetic damage contrasts with sound function.']]),
p('n1-059','Affirm one outcome while excluding a contrasting one.','Vます stem + こそすれ … negative','formal','Commonly stresses that the opposite result cannot be expected.','Use the verb stem before こそすれ.',[
['感謝[こそすれ]、恨んではいない。','I feel gratitude, certainly no resentment.','The positive feeling excludes its opposite.'],['負担は増え[こそすれ]、減りはしない。','The burden will increase rather than decrease.','A directional contrast.'],['応援[こそすれ]、邪魔はしない。','I will support you, never obstruct you.','An emphatic assurance.']]),
p('n1-060','Acknowledge an emphasized fact before contrasting it with another.','N + こそ … が / けれど; Vます stem + こそすれ is separate','formal/neutral','Focuses a limitation while preserving a contrasting positive point.','こそ supplies emphasis; が or けれど carries the contrast.',[
['値段[こそ]高い[が]、長く使える。','It is expensive, admittedly, but it lasts.','Cost contrasts with durability.'],['部屋[こそ]狭い[けれど]、日当たりはいい。','The room may be small, but it gets good sunlight.','Concedes a limited drawback.'],['形[こそ]違う[が]、仕組みは同じだ。','Its shape is different, but the mechanism is the same.','Surface and structure contrast.']]),
p('n1-061','Emphasize that every member of a set shares an outcome.','ことごとく + predicate','written/emphatic','Often appears with comprehensive failure or destruction.','It means all members, not merely many of them.',[
['提案は[ことごとく]却下された。','Every proposal was rejected.','No proposal was spared.'],['予想が[ことごとく]外れた。','Every prediction turned out wrong.','A complete set of failures.'],['古い記録を[ことごとく]調べ直した。','I reexamined every old record.','Comprehensive coverage of records.']]),
p('n1-062','Express the highest degree of a feeling or evaluation.','Adjective + ことこの上ない; この上ない + N; この上なく + adjective','formal/emotional','Often used for happiness, honor, or inconvenience.','この上ない modifies a noun; この上なく modifies a predicate.',[
['皆に会えてうれしい[ことこの上ない]。','I could not be happier to see everyone.','An intense personal feeling.'],['[この上ない]喜びを感じた。','I felt the greatest joy.','The expression modifies 喜び.'],['返事を待つ時間は[この上なく]長く感じた。','The wait for the reply felt unbearably long.','Degree modifies the felt length.']]),
p('n1-063','Give one contributing reason among several.','Plain clause + こともあって; N / な-adjective + なこともあって','neutral','The reason helps explain a result but is not necessarily sufficient alone.','も implies additional causes or circumstances.',[
['休日だった[こともあって]、道は混んでいた。','Partly because it was a holiday, the roads were busy.','A contributing circumstance.'],['駅が近い[こともあって]、この部屋に決めた。','I chose this apartment partly because it is near the station.','One factor in a decision.'],['初めての発表だった[こともあって]緊張した。','I was nervous partly because it was my first presentation.','Experience contributes to emotion.']]),
p('n1-064','Describe achieving something without an ordinarily expected step.','V dictionary + ことなしに','formal','Often stresses an omitted experience, effort, or procedure.','Use dictionary form, not a negative verb before ことなしに.',[
['現場を見る[ことなしに]結論は出せない。','We cannot reach a conclusion without seeing the site.','The step is necessary.'],['誰も傷つける[ことなしに]解決したい。','I want to resolve it without hurting anyone.','An unwanted consequence is avoided.'],['諦める[ことなしに]研究を続けた。','She continued her research without giving up.','A sustained course of action.']]),
p('n1-065','Ask for precautions against a specified event.','V dictionary / negative + ことのないように','formal','Usually appears in warnings or careful instructions.','The following request should prevent the event named before こと.',[
['書類をなくす[ことのないように]保管してください。','Please store the documents so they do not get lost.','A prevention-oriented instruction.'],['同じ事故を繰り返す[ことのないように]点検を増やす。','We will increase inspections to prevent a repeat accident.','A future safeguard.'],['連絡を忘れる[ことのないように]メモした。','I made a note so I would not forget to contact them.','A personal precaution.']]),
p('n1-066','Give a formal explanation or excuse based on a circumstance.','Plain clause + こととて; N + の / な-adjective + な + こととて','formal/old-fashioned','Often softens a request for understanding or forgiveness.','Its apologetic literary tone is unusual in everyday chat.',[
['不慣れな[こととて]、失礼があればお許しください。','I am inexperienced, so please forgive any discourtesy.','A formal request for understanding.'],['急な[こととて]、十分な準備ができませんでした。','It was sudden, so I could not prepare fully.','Explains inadequate preparation.'],['何も知らぬ[こととて]、見当違いの質問をした。','Knowing nothing about it, I asked an irrelevant question.','A literary excuse for a mistake.']]),
p('n1-067','Prefer a drastic alternative to an unacceptable choice.','V dictionary + くらいなら','neutral/emphatic','The first action is strongly rejected; the second is preferable.','This is not an ordinary neutral conditional.',[
['嘘をつく[くらいなら]黙っていたい。','I would rather stay silent than lie.','Rejects the first choice.'],['捨てる[くらいなら]私にください。','If you are going to throw it away, please give it to me.','Offers a better alternative.'],['無理に続ける[くらいなら]一度休もう。','Rather than force ourselves to continue, let’s take a break.','A preferable response to an undesirable action.']]),
p('n1-068','Limit what is true or possible to a narrow case.','Plain clause / N + くらいのものだ','neutral','Often follows a limited example such as 私 or 週末.','The phrase restricts the set; it does not simply express size.',[
['この道を通るのは地元の人[くらいのものだ]。','About the only people using this road are locals.','A narrowly limited group.'],['ゆっくり読めるのは週末[くらいのものだ]。','Weekends are about the only time I can read at leisure.','A scarce opportunity.'],['私にできるのは話を聞く[くらいのものだ]。','About all I can do is listen.','Modestly limits ability.']]),
p('n1-069','Present an action as a simple fallback or explain a limited intention.','V dictionary / た + までだ / までのことだ','neutral/firm','Dictionary form often expresses resolve; past form limits an explanation.','It can sound dismissive when used to defend an action.',[
['バスがなければ歩く[までだ]。','If there is no bus, I will simply walk.','A determined fallback.'],['心配だったから電話した[までのことだ]。','I only called because I was worried.','Limits the motive.'],['失敗したらやり直す[までだ]。','If it fails, I will just do it again.','An uncomplicated response to failure.']]),
p('n1-070','Say that an action is unnecessary because the answer is obvious.','V dictionary + までもない / までもなく','neutral/formal','Often with 言う, 聞く, or 調べる.','Unlike までだ, it denies a need to act.',[
['その説明なら聞く[までもない]。','There is no need to hear that explanation.','The speaker already understands.'],['言う[までもなく]安全が最優先だ。','Needless to say, safety comes first.','Introduces an obvious principle.'],['自分で分かるので調べる[までもない]。','I know it myself, so there is no need to look it up.','Existing knowledge makes a step unnecessary.']]),
p('n1-071','Condemn behavior as unacceptable for someone in a role.','V dictionary + まじき + N; する → する / すまじき','formal/literary','Often follows a role marked by にある.','まじき modifies a noun and is not an everyday prohibition ending.',[
['教師にある[まじき]発言だった。','It was a remark unworthy of a teacher.','A role imposes a standard.'],['公の場で許す[まじき]行為だ。','It is conduct that must not be tolerated in public.','A strong moral prohibition.'],['責任者としてある[まじき]態度だ。','That attitude is unacceptable for someone in charge.','Condemns failure to meet a duty.']]),
p('n1-072','Describe doing an action repeatedly or with great intensity.','Vます stem + まくる','colloquial','Often suggests uncontrolled or enthusiastic repetition.','It is stronger and more informal than simply たくさん.',[
['休日は本を読み[まくった]。','I read book after book on my day off.','Enthusiastic repetition.'],['蚊に刺され[まくった]。','I got bitten by mosquitoes all over.','Repeated passive experience.'],['旅先で写真を撮り[まくった]。','I took masses of photos on the trip.','Intensive activity.']]),
p('n1-073','Describe being covered or soiled with an unwanted substance.','N + まみれ','neutral','Usually with mud, blood, sweat, dust, or analogous contamination.','For pleasant coverage, まみれ is usually unsuitable.',[
['靴が泥[まみれ]になった。','My shoes became covered in mud.','Physical soiling.'],['作業着は油[まみれ]だ。','The work clothes are covered in oil.','A substance coats the surface.'],['古い箱はほこり[まみれ]だった。','The old box was covered in dust.','An unwanted coating.']]),
p('n1-074','Emphasize total absence or a complete difference.','まるっきり + negative / different state','colloquial','An emphatic conversational form of まるきり.','It does not mean a small or partial difference.',[
['説明を聞いても[まるっきり]分からない。','Even after the explanation, I understand absolutely nothing.','Complete lack of understanding.'],['写真とは[まるっきり]違う。','It is completely different from the photograph.','An emphatic contrast.'],['その話は[まるっきり]初耳だ。','That is entirely new to me.','No prior knowledge.']]),
p('n1-075','Describe the emergence of a suggestive atmosphere or quality.','Established N + めく / めいた','literary/neutral','Common with 春, 謎, and 冗談.','Unlike ぶる, it need not imply deliberate pretence.',[
['日差しが春[めいて]きた。','The sunlight is starting to feel springlike.','A seasonal quality emerges.'],['彼は謎[めいた]笑みを浮かべた。','He wore an enigmatic smile.','The smile suggests mystery.'],['冗談[めいた]言葉に本音がにじんだ。','True feelings showed through the joking words.','The words have the air of a joke.']]),
p('n1-076','Treat a situation as effectively equivalent to another.','N / Vた + も同然だ','neutral/emphatic','The situations are practically, rather than literally, identical.','With nouns such as ただ, spacing does not change the construction.',[
['返事がないなら拒否[も同然だ]。','No reply is practically a refusal.','Infers an effective outcome.'],['ここまで来れば完成した[も同然だ]。','Having come this far, it is as good as finished.','The remaining gap is treated as small.'],['百円ならただ[も同然だ]。','At a hundred yen, it is practically free.','An emphatic value judgment.']]),
p('n1-077','Acknowledge one factor while giving special weight to another.','N + もさることながら + N + も','formal','The second factor usually receives the main emphasis.','It does not dismiss the importance of the first factor.',[
['味[もさることながら]、香りもすばらしい。','The taste is excellent, and the aroma is remarkable too.','Adds a particularly notable quality.'],['技術[もさることながら]、粘り強さが必要だ。','Skill matters, but perseverance is especially necessary.','Highlights the second requirement.'],['内容[もさることながら]、表紙にも魅力がある。','The contents are appealing, and so is the cover.','Both qualities count.']]),
p('n1-078','Criticize someone for not even doing an expected action.','Vます stem + もしないで','colloquial/critical','Emphasizes omission before another action or judgment.','The stem is required: 調べもしないで, not 調べるもしないで.',[
['調べ[もしないで]無理だと言わないで。','Do not call it impossible without even checking.','An expected preliminary step is omitted.'],['挨拶[もしないで]帰ってしまった。','He left without even saying goodbye.','A basic courtesy is missing.'],['読み[もしないで]本を批判した。','She criticized the book without even reading it.','The omission undermines a judgment.']]),
p('n1-079','Mark that a former situation has already ceased to apply.','もはや + changed state / negative','formal/neutral','Often signals an irreversible threshold.','It is stronger than simply もう in casual timing statements.',[
['[もはや]延期はできない。','We can no longer postpone it.','A limit has been reached.'],['ここは[もはや]静かな村ではない。','This is no longer a quiet village.','A past description has ceased to fit.'],['彼の名は[もはや]誰もが知っている。','By now, everyone knows his name.','A new state is established.']]),
p('n1-080','Give a personal reason with an explanatory or apologetic tone.','Plain form + もので; N / な-adjective + なもので','conversational/polite','Often explains the speaker’s own circumstances.','It can sound like an excuse; avoid using it as an impersonal proof.',[
['道が混んでいた[もので]、遅れました。','The roads were busy, so I was late.','An apologetic explanation.'],['初めてな[もので]、手順を教えてください。','It is my first time, so please explain the procedure.','Circumstances motivate a request.'],['子供が寝ている[もので]、小声でお願いします。','My child is asleep, so please speak quietly.','A personal reason for a request.']]),
p('n1-081','Regret that an outcome differed from an unrealized alternative.','Plain clause + ものを','literary/emotional','Often follows のに-like counterfactual reasoning.','It carries regret or blame, rather than a neutral contrast.',[
['一言聞けば分かった[ものを]、彼は勝手に決めた。','One question would have cleared it up, but he decided on his own.','A missed simple solution.'],['早く出れば間に合った[ものを]。','If only we had left earlier, we would have made it.','The consequence is left implicit.'],['知らせてくれれば迎えに行った[ものを]。','If you had let me know, I would have come to meet you.','Regret over an unrequested offer.']]),
p('n1-082','Present a conclusion as an evidence-based assessment.','Plain clause + ものと思われる / ものと見られる','formal/reporting','Common in reports; the assessor is often left unnamed.','It signals an inference, not direct observation of the conclusion.',[
['故障は湿気が原因である[ものと見られる]。','Moisture is believed to have caused the failure.','A technical assessment.'],['需要は今後も増える[ものと思われる]。','Demand is expected to keep growing.','A forecast rather than certainty.'],['遺跡は千年前の建物である[ものと見られる]。','The ruins are thought to be a thousand-year-old building.','An interpretation of evidence.']]),
p('n1-083','Set out a rule, provision, or agreed assumption.','V dictionary / negative + ものとする','formal/legal','The sentence establishes what will apply.','Distinguish rule-setting from a personal prediction using と思う.',[
['申請は本人が行う[ものとする]。','Applications shall be made by the person concerned.','A procedural rule.'],['交通費は各自で負担する[ものとする]。','Each participant shall cover their own travel costs.','Allocates responsibility.'],['計算では端数を切り捨てる[ものとする]。','For the calculation, fractions shall be rounded down.','Establishes a working convention.']]),
p('n1-084','Proceed on the assumption that a stated situation holds.','Plain clause + ものとして','formal','Useful in simulations, planning, and conditional reasoning.','The assumed situation is not necessarily a verified fact.',[
['全員が参加する[ものとして]席を用意した。','I arranged seats assuming everyone would attend.','An assumption guides preparation.'],['雨は降らない[ものとして]計画を立てよう。','Let’s plan on the assumption that it will not rain.','A provisional planning basis.'],['費用は一定である[ものとして]計算する。','We calculate assuming the cost is constant.','A model simplifies reality.']]),
p('n1-085','Connect alternatives in a formal choice.','N / clause + もしくは + N / clause','formal','Often used in rules and instructions for alternatives.','Use it for choices, not for adding two simultaneous facts.',[
['印鑑[もしくは]署名が必要です。','A seal or a signature is required.','Either item satisfies a requirement.'],['郵送[もしくは]窓口で提出してください。','Please submit it by mail or at the counter.','Two submission routes.'],['延期するか、[もしくは]中止するかを決める。','We will decide whether to postpone or cancel.','A formal decision between actions.']]),
p('n1-086','Portray an appearance or action as almost reaching an extreme.','Vない stem + んばかりに / の / だ; する → せんばかり','literary/emphatic','The extreme action need not actually occur.','Do not add ん to the full ない form.',[
['彼は泣か[んばかりに]頼んだ。','He pleaded as though he were about to cry.','An intense visible emotion.'],['木は倒れ[んばかりに]揺れた。','The tree swayed as if it were about to fall.','Appearance approaches an extreme.'],['皆は飛び上がら[んばかりの]喜びようだった。','Everyone was so delighted they seemed ready to leap into the air.','The form modifies a description of joy.']]),
p('n1-087','Express a determined purpose in a literary style.','Vない stem + んがために / の; する → せんがため','literary/formal','Typically a deliberate effort toward an important goal.','It is a purpose construction, not a causal explanation.',[
['真実を伝え[んがために]筆を執った。','I took up my pen in order to tell the truth.','A solemn purpose.'],['技を極め[んがために]修業を重ねた。','She trained repeatedly to master her craft.','Determination over time.'],['名を残さ[んがための]行動ではない。','This is not an action taken to leave a name behind.','The purpose phrase modifies 行動.']]),
p('n1-088','Preserve an original state or describe an action in that state.','N / Vます stem + ながらに; N + ながらの','literary/neutral','Common with 生まれ, 昔, 居, and 涙.','This entry concerns an unchanged state, rather than doing two tasks.',[
['祖父は昔[ながらの]道具を使う。','My grandfather uses traditional tools.','The old form is retained.'],['居[ながらに]して世界の映像を見られる。','We can see images from around the world without leaving home.','The location remains unchanged.'],['彼女は涙[ながらに]事情を語った。','She explained the situation through tears.','A state accompanies the speech.']]),
p('n1-089','Set a lesser acceptable outcome below an ideal one.','Vない + までも; adjective negative + までも','formal/neutral','The second clause states a lower standard or partial outcome.','The negative belongs to the ideal that may not be reached.',[
['優勝でき[ないまでも]、決勝には進みたい。','Even if we cannot win, I want to reach the final.','A lower target remains.'],['毎日とは言わ[ないまでも]、週に一度は連絡して。','I am not asking for every day, but contact me at least once a week.','Lowers an ideal frequency.'],['賛成し[ないまでも]、話は聞いてほしい。','Even if you do not agree, I want you to hear me out.','Requests a minimum response.']]),
p('n1-090','Leave open a possibility while attaching a condition or reservation.','Vない + ものでもない','cautious/neutral','Often amounts to a conditional willingness.','The double negative weakly allows the action; it is not a firm promise.',[
['条件が合えば引き受け[ないものでもない]。','If the terms suit me, I might take it on.','A qualified willingness.'],['説明次第では理解でき[ないものでもない]。','With the right explanation, I might be able to understand.','A possible change in judgment.'],['工夫すれば一日で終わら[ないものでもない]。','With some ingenuity, finishing in one day is not impossible.','A cautious possibility.']]),
p('n1-091','Wish for a solution that seems difficult to achieve.','Vない + ものか / ものだろうか','reflective/emotional','Often paired with potential verbs or 何とか.','The question expresses a wish, not an accusation by default.',[
['何とか費用を減らせ[ないものか]。','Is there no way we could reduce the cost?','Searches for a desired solution.'],['皆が安心して暮らせ[ないものだろうか]。','Could we not make it possible for everyone to live securely?','A reflective wish.'],['この音をもう少し小さくでき[ないものか]。','Could we somehow make this sound a little quieter?','Desires an improvement.']]),
p('n1-092','Keep an unwelcome possibility in view despite uncertainty.','Vない + とも限らない','cautious','Common in warnings about something that could still occur.','The whole expression allows the positive event: 起きないとも限らない means it might happen.',[
['また停電し[ないとも限らない]。','There could be another power outage.','A precaution against recurrence.'],['古い橋が崩れ[ないとも限らない]。','The old bridge might collapse.','A risk cannot be excluded.'],['噂が本人に伝わら[ないとも限らない]。','The rumor could reach the person concerned.','A warning against assuming secrecy.']]),
p('n1-093','State that something is essential for a result.','N + なくしては + negative','formal/emphatic','Usually accompanies a negative possibility or achievement.','Unlike なしに, it strongly stresses indispensability.',[
['信頼[なくしては]協力は成り立たない。','Cooperation cannot exist without trust.','An indispensable foundation.'],['練習[なくしては]上達は望めない。','Improvement cannot be expected without practice.','A necessary process.'],['対話[なくしては]解決に至らない。','We cannot reach a solution without dialogue.','An essential means.']]),
p('n1-094','Compare a level or condition to a familiar standard.','N + 並み / 並みの / 並みに','neutral','Used for ability, size, price, or treatment.','It refers to a comparable level, not literal identity.',[
['彼の腕前はプロ[並み]だ。','His skill is at a professional level.','A standard of ability.'],['今年は真夏[並みの]暑さが続く。','Heat like midsummer keeps continuing this year.','A familiar degree of heat.'],['新人も先輩[並みに]働いている。','The newcomer works at the same level as the experienced staff.','Compares performance.']]),
p('n1-095','React strongly to the degree or nature of something.','なんという + N; なんと … ことか; なんて … んだ','emotional','Can express admiration, surprise, or dismay.','Exclamatory なんて differs from the dismissive listing use.',[
['[なんという]美しい景色だ。','What a beautiful view!','Admiration at a sight.'],['[なんと]静かな場所だろう。','What a quiet place this is.','A reflective exclamation.'],['[なんて]ひどいことをするんだ。','What a terrible thing to do!','Strong disapproval.']]),
p('n1-096','Introduce a decisive reason that explains a reaction.','何しろ + reason','conversational/neutral','Often followed by から or ので.','It foregrounds a reason rather than simply changing topic.',[
['[何しろ]初めてなので、緊張しています。','After all, it is my first time, so I am nervous.','An especially relevant reason.'],['[何しろ]人数が多いから、準備が大変だ。','There are so many people that preparing is hard.','The scale explains the burden.'],['早めに出よう。[何しろ]道が狭い。','Let’s leave early; the road is very narrow, after all.','A reason supports a suggestion.']]),
p('n1-097','Highlight a distinctive strength that only a particular source offers.','N + ならではの + N; N + ならではだ','positive/emphatic','Typically praises a characteristic tied to a place, person, or craft.','Use の to modify a noun; do not insert だ before ならでは.',[
['手作り[ならではの]温かさがある。','It has a warmth unique to handmade things.','A distinctive positive quality.'],['この眺めは山頂[ならではだ]。','This view is something only the summit can offer.','A location-specific experience.'],['職人[ならではの]工夫が光る。','The ingenuity unique to a craftsperson shines through.','Expertise creates a special result.']]),
p('n1-098','Exclude a case as understandable while criticizing another.','N + ならいざしらず / はいざしらず','formal/critical','The first case is set aside; the second is judged differently.','It does not mean the speaker literally knows nothing about the first noun.',[
['子供[ならいざしらず]、大人が知らないとは驚いた。','It might be understandable for a child, but an adult not knowing surprised me.','Different standards apply.'],['昔[はいざしらず]、今はその方法は使えない。','Whatever was true in the past, that method cannot be used now.','Separates eras.'],['冗談[ならいざしらず]、本気なら困る。','A joke would be one thing, but it is a problem if you mean it.','Excludes a harmless interpretation.']]),
p('n1-099','Narrate an immediate, often unexpected action.','V dictionary + なり + past event','written/narrative','Usually the same person does both actions.','Different from なりに, which means in one’s own way.',[
['彼は部屋に入る[なり]窓を開けた。','He opened the window as soon as he entered the room.','One actor performs consecutive actions.'],['娘は顔を見る[なり]泣き出した。','My daughter burst into tears the moment she saw my face.','An immediate emotional response.'],['客は席に着く[なり]注文した。','The customer ordered as soon as he sat down.','A rapid follow-up action.']]),
p('n1-100','Recognize an approach appropriate to someone’s own circumstances.','N / plain form + なりに; N + なりの + N','neutral','Often acknowledges effort despite limited ability or resources.','It does not necessarily mean doing something poorly.',[
['子供[なりに]理由を考えている。','The child is thinking through the reasons in their own way.','Recognizes age-appropriate thought.'],['私[なりの]答えを出した。','I reached an answer of my own.','An individual perspective.'],['狭い[なりに]工夫して暮らしている。','We make the best of living in a small space.','Adaptation to a limitation.']]),
p('n1-101','Offer a small minimum or an unrestricted possible choice.','N + なりとも; question word + なりと','formal/old-fashioned','Often with 少し or a small amount.','Do not confuse with なり～なり listing alternatives.',[
['少し[なりとも]お役に立てれば幸いです。','I would be glad to help even a little.','A modest minimum contribution.'],['一目[なりとも]会いたかった。','I wanted to see her, even for a moment.','A minimal desired opportunity.'],['何[なりと]お申し付けください。','Please let me know whatever you need.','A formal open offer.']]),
p('n1-102','Suggest two representative options for taking action.','N / V dictionary + なり … + なり','neutral','Alternatives are examples; other suitable choices may exist.','Do not read the pair as requiring both actions.',[
['電話する[なり]メールする[なり]、連絡して。','Contact me, whether by calling or emailing.','The method is flexible.'],['水[なり]お茶[なり]飲んで休もう。','Let’s rest with some water or tea.','Representative drink choices.'],['辞書で調べる[なり]人に聞く[なり]して確かめて。','Check it by using a dictionary or asking someone.','Suggests practical alternatives.']]),
p('n1-103','Describe the absence of a normally expected thing or step.','N + なしに / なしで; V dictionary + ことなしに','neutral','The noun may be permission, help, notice, or a resource.','Use なくしては for a strongly indispensable condition.',[
['予約[なしで]入れますか。','Can I enter without a reservation?','A missing arrangement.'],['断り[なしに]写真を使わないで。','Do not use the photo without permission.','An expected prerequisite is absent.'],['辞書[なしで]この手紙を読んだ。','I read this letter without a dictionary.','A tool was not used.']]),
p('n1-104','Add items to an accumulating list.','N + に + N; N + に加えて is related','neutral','This entry concerns addition, especially lists of orders or burdens.','This is not the destination or time-marking に.',[
['注文はコーヒー[に]トーストです。','The order is coffee and toast.','Two ordered items.'],['今日は会議[に]面談で忙しい。','I am busy with meetings and interviews today.','Activities accumulate.'],['土産はお菓子[に]お茶を選んだ。','For gifts, I chose sweets and tea.','Adds one selection to another.']]),
p('n1-105','Judge something worthy of a particular response or evaluation.','N / V dictionary + に値する','formal','Often with 賞賛, 注目, 評価, and 信頼.','値する means merit, not a physical price.',[
['この発見は注目[に値する]。','This discovery deserves attention.','A scholarly evaluation.'],['彼の行動は称賛[に値する]。','His conduct deserves praise.','A positive judgment.'],['その資料は保存する[に値する]。','Those materials are worth preserving.','A worthwhile action.']]),
p('n1-106','Place a statement within a distinctive situation or era.','N + にあって（は / も）','formal/written','Often frames unusual conditions that shape an action.','にあって presents the setting; とあって presents a salient reason.',[
['非常時[にあって]も冷静さを失わなかった。','Even in an emergency, she stayed calm.','The circumstances are challenging.'],['変革期[にあって]、教育の役割が問われている。','In this period of change, the role of education is being questioned.','An era frames the issue.'],['厳しい環境[にあって]、この木は生き延びた。','This tree survived in a harsh environment.','The setting makes survival notable.']]),
p('n1-107','Make a sharp comparison between contrasting cases.','N + に引き換え; clause + のに引き換え','neutral/written','Often compares people or past and present unfavorably.','The second case should contrast meaningfully with the first.',[
['昨日[に引き換え]、今日は暖かい。','In contrast to yesterday, today is warm.','Contrasting weather.'],['兄[に引き換え]、弟は口数が少ない。','Unlike his older brother, the younger one says little.','A character contrast.'],['評判の良さ[に引き換え]、実物は平凡だった。','Despite its excellent reputation, the actual item was ordinary.','Expectation and reality diverge.']]),
p('n1-108','Mark arrival at a consequential stage or outcome.','V dictionary / N + に至る / に至った','formal','Often describes a process culminating in a decision or event.','It need not imply a welcome achievement.',[
['長い協議の末、合意[に至った]。','After long discussions, we reached an agreement.','A process reaches a conclusion.'],['彼は退職する[に至った]経緯を語った。','He described the circumstances that led him to resign.','A consequential final action.'],['小さな誤解が裁判[に至った]。','A small misunderstanding led to a court case.','An escalation to an outcome.']]),
p('n1-109','Include even the farthest or smallest endpoint of a range.','N + に至るまで','formal','Often with から to frame a broad range.','It marks inclusive extent, not merely a destination.',[
['設計から包装[に至るまで]一人で行う。','I do everything myself, from design through packaging.','A complete workflow.'],['細部[に至るまで]丁寧に描かれている。','It is carefully drawn down to the finest detail.','The smallest elements are included.'],['店員の服装[に至るまで]統一されている。','Even the staff’s clothing is coordinated.','An unexpectedly thorough extent.']]),
p('n1-110','Emphasize that something remains unchanged even at a late stage.','V dictionary / N + に至っても','formal','Usually followed by a negative or unchanged response.','The point is persistence despite escalation, not simply reaching a stage.',[
['裁判[に至っても]彼は謝罪しなかった。','Even when it reached court, he did not apologize.','A response remains absent.'],['倒産する[に至っても]経営陣は責任を認めなかった。','Even when the company went bankrupt, management denied responsibility.','A serious endpoint fails to change a stance.'],['締め切り当日[に至っても]返事がない。','Even on the day of the deadline, there is no reply.','A delay persists to the limit.']]),
p('n1-111','Single out an extreme case for special comment.','N + に至っては','formal','Often advances from earlier examples to a particularly striking one.','A suitable context establishes the comparison or escalation.',[
['大人も迷う。子供[に至っては]地図さえ読めない。','Even adults get lost; children cannot even read the map.','An additional case is more extreme.'],['他の部屋も寒いが、廊下[に至っては]息が白い。','The rooms are cold, but in the corridor you can see your breath.','A striking endpoint of comparison.'],['兄も遅刻したが、弟[に至っては]欠席だった。','My older brother was late, while my younger brother did not come at all.','The second failure is greater.']]),
p('n1-112','Attribute an evaluation to a particular person’s perspective.','Person + に言わせれば','neutral','Often introduces an opinion different from the speaker’s.','It reports a viewpoint, not necessarily words spoken verbatim.',[
['父[に言わせれば]、この靴はまだ新しい。','According to my father, these shoes are still new.','A different standard of age.'],['専門家[に言わせれば]、修理は簡単らしい。','From an expert’s perspective, the repair seems simple.','Expertise changes the assessment.'],['彼女[に言わせれば]、これは失敗ではない。','In her view, this is not a failure.','A personal interpretation.']]),
p('n1-113','Deny that an issue belongs exclusively to one case.','N + に限ったことではない','neutral/formal','Usually broadens a problem or tendency to other groups.','It does not deny that the named case has the issue.',[
['人手不足は地方[に限ったことではない]。','Staff shortages are not confined to rural areas.','The problem extends elsewhere.'],['緊張するのは新人[に限ったことではない]。','It is not only newcomers who get nervous.','A feeling crosses experience levels.'],['この悩みは私[に限ったことではない]。','This concern is not unique to me.','Others share the concern.']]),
p('n1-114','Show what someone’s skill or handling does to a situation.','Person + にかかっては / にかかると / にかかったら','neutral/expressive','Can praise ability or criticize someone’s treatment.','Different from にかかっている meaning depend on.',[
['彼[にかかると]難問も遊びになる。','In his hands, even a hard problem becomes a game.','Exceptional handling transforms a task.'],['あの編集者[にかかったら]長い文章も半分になる。','In that editor’s hands, even a long piece becomes half its length.','Skillful compression.'],['祖母[にかかっては]私もまだ子供だ。','As far as my grandmother is concerned, I am still a child.','Someone’s way of treating a person.']]),
p('n1-115','Identify the factor that determines success or an outcome.','N / question clause + にかかっている','neutral/formal','The preceding element carries decisive influence.','This is dependence, not the physical act of hanging.',[
['成功は準備[にかかっている]。','Success depends on preparation.','A determining factor.'],['勝敗は最後まで集中できるか[にかかっている]。','The result depends on whether we can stay focused to the end.','An embedded question names the condition.'],['計画の実現は予算[にかかっている]。','Realizing the plan depends on the budget.','Resources are decisive.']]),
p('n1-116','Use a circumstance as a convenient pretext for another aim.','N + にかこつけて','critical','The stated reason does not fully explain the real motive.','It often implies opportunism, unlike neutral を機に.',[
['出張[にかこつけて]温泉へ行った。','He used his business trip as a pretext to visit a hot spring.','A convenient excuse for leisure.'],['点検[にかこつけて]部屋をのぞいた。','She used the inspection as an excuse to peek into the room.','The real aim is intrusive.'],['誕生日[にかこつけて]自分の欲しい物を買った。','I used the birthday as an excuse to buy something I wanted.','The celebration masks self-interest.']]),
p('n1-117','Blame absorption in one thing for neglecting another.','N + にかまけて','critical','Usually followed by an omitted duty or unwelcome result.','It implies neglect, not simply being busy.',[
['仕事[にかまけて]家族への連絡を怠った。','Absorbed in work, I neglected to contact my family.','An important relationship is neglected.'],['遊び[にかまけて]宿題を忘れた。','I was so caught up in playing that I forgot my homework.','Pleasure displaces a duty.'],['目先の利益[にかまけて]安全を軽視した。','Preoccupied with immediate profit, they neglected safety.','A short-term concern obscures a responsibility.']]),
p('n1-118','Say that a feeling or situation is easy to infer.','V dictionary + に難くない','formal','Most common with 想像する and 察する.','難くない is read かたくない here.',[
['彼の喜びは想像する[に難くない]。','It is easy to imagine his joy.','A feeling is readily inferred.'],['家族の不安は察する[に難くない]。','It is easy to understand the family’s anxiety.','Empathy follows from circumstances.'],['混乱が起きることは想像する[に難くない]。','It is not hard to imagine confusion arising.','A foreseeable consequence.']]),
p('n1-119','Connect stories, events, or details to a central subject.','N + にまつわる + N','neutral/written','Often used for legends, memories, mysteries, or episodes.','It indicates association, not necessarily direct causation.',[
['この橋[にまつわる]伝説を聞いた。','I heard a legend associated with this bridge.','A place has a surrounding story.'],['名前[にまつわる]思い出を語った。','She spoke about memories connected with her name.','Personal associations.'],['発見[にまつわる]経緯を記録する。','We will record the circumstances surrounding the discovery.','Related background details.']]),
p('n1-120','Act in accordance with an established norm or procedure.','N + に則って','formal','The noun is usually a law, rule, principle, or custom.','Use に即して for adapting to actual conditions.',[
['規則[に則って]処理します。','We will handle it in accordance with the rules.','A procedural standard.'],['伝統[に則って]式を行った。','We held the ceremony according to tradition.','A customary form.'],['法[に則って]権利を守る。','We protect rights in accordance with the law.','A legal basis.']]),
p('n1-121','Act ahead of others or before a larger event begins.','N + に先駆けて; N + に先駆ける + N','formal','Often stresses a pioneering step or advance launch.','It implies precedence, not simply any unrelated earlier time.',[
['全国発売[に先駆けて]試作品を公開した。','We unveiled the prototype ahead of the nationwide launch.','A preview precedes a launch.'],['他社[に先駆けて]新素材を採用した。','We adopted the new material before other companies.','A pioneering business decision.'],['開会[に先駆けて]黙祷を捧げた。','We observed a moment of silence before the opening.','An advance ceremonial action.']]),
p('n1-122','Find an action emotionally too painful to perform or witness.','V dictionary + に忍びない','formal/emotional','Common with 見る, 聞く, 捨てる, and 断る.','This is emotional reluctance, not a physical inability.',[
['思い出の服は捨てる[に忍びない]。','I cannot bear to throw away these clothes full of memories.','Attachment blocks disposal.'],['傷ついた鳥の姿は見る[に忍びない]。','I cannot bear to look at the injured bird.','The sight is painful.'],['彼の必死な願いは断る[に忍びない]。','I cannot bear to refuse his desperate request.','Compassion makes refusal hard.']]),
p('n1-123','Apply a limit or difficulty even to the named party.','N + にしたところで; plain clause + としたところで','neutral/formal','Often followed by a negative or limited expectation.','It does not guarantee that the hypothetical condition is true.',[
['専門家[にしたところで]未来は断言できない。','Even an expert cannot predict the future with certainty.','Expertise has limits.'],['今出発する[としたところで]間に合わない。','Even if we leave now, we will not make it.','A favorable action cannot change the result.'],['私[にしたところで]事情を知っていたわけではない。','I did not know the circumstances either.','Includes the speaker in a limitation.']]),
p('n1-124','Emphasize a stage, short span, or surprising combination of qualities.','N / time expression + にして','formal','Its interpretation depends on the noun and surrounding predicate.','Do not treat all にして uses as a simple synonym for で.',[
['祖父は八十歳[にして]初めて海外へ行った。','My grandfather went abroad for the first time at eighty.','A notable stage of life.'],['景色は一夜[にして]変わった。','The landscape changed overnight.','An unexpectedly short span.'],['彼女は研究者[にして]優れた画家でもある。','She is a researcher and also an excellent painter.','Two identities are formally combined.']]),
p('n1-125','Adapt action to facts, conditions, or actual needs.','N + に即して / に即した + N','formal','Typically with 現実, 実情, 状況, and needs.','For following an established rule as a norm, に則って is more specific.',[
['実情[に即した]支援が必要だ。','Support suited to the actual circumstances is needed.','Practical conditions shape support.'],['現場の声[に即して]計画を直す。','We will revise the plan in line with feedback from the site.','Real feedback guides revision.'],['事実[に即して]説明してください。','Please explain it in keeping with the facts.','The explanation must reflect reality.']]),
p('n1-126','Judge whether something can bear examination or evoke an intense feeling.','V dictionary / N + に耐える / に耐えない; emotion noun + に堪えない','formal','見るに耐えない concerns an unbearable sight; 感謝に堪えない expresses overwhelming thanks.','Use 耐 for withstanding or enduring; overwhelming emotion conventionally uses 堪, as in 感謝に堪えない.',[
['この論文は厳しい批判[に耐える]。','This paper can withstand rigorous criticism.','Its quality stands up to scrutiny.'],['荒れ果てた庭は見る[に耐えない]。','The devastated garden is unbearable to look at.','A distressing sight.'],['皆様のご支援に感謝[に堪えません]。','I cannot express how grateful I am for your support.','A formal formula for intense gratitude.']]),
p('n1-127','Dismiss something as unworthy of concern or evaluation.','V dictionary / N + に足らない / に足りない','formal','Common with 取る, 恐れる, and 信頼.','The construction evaluates worth; it is not a shortage of quantity.',[
['取る[に足らない]噂は忘れよう。','Let’s forget that insignificant rumor.','A fixed expression for insignificance.'],['相手は恐れる[に足りない]。','The opponent is not worth fearing.','Dismisses a threat.'],['根拠がなく、信頼[に足らない]報告だ。','It is an unsubstantiated report that cannot be trusted.','Insufficient grounds for confidence.']]),
p('n1-128','Say that someone or something merits trust or consideration.','V dictionary / N + に足る / に足りる','formal','Common with 信頼, 尊敬, and 検討.','足る here is a worthiness judgment, not simply having enough objects.',[
['彼は信頼[に足る]人物だ。','He is a person worthy of trust.','Evaluates character.'],['検討する[に足りる]証拠が集まった。','We have gathered evidence worthy of examination.','The material merits attention.'],['これは後世に残す[に足る]作品だ。','This is a work worth preserving for future generations.','A lasting artistic value.']]),
p('n1-129','Assess something against an explicit standard or evidence.','N + に照らして / に照らすと','formal','Common standards include rules, experience, and facts.','It is a figurative comparison, not literal illumination.',[
['規定[に照らして]申請を審査する。','We will assess the application against the regulations.','A standard guides evaluation.'],['経験[に照らすと]この見積もりは甘い。','Judging from experience, this estimate is too optimistic.','Experience supplies a benchmark.'],['事実[に照らして]証言を確認した。','We checked the testimony against the facts.','Evidence tests a claim.']]),
p('n1-130','Extend a phenomenon beyond its initial range.','N / plain clause + にとどまらず','formal','The second clause expands scope, effect, or degree.','It does not mean physically staying in one place here.',[
['影響は国内[にとどまらず]海外にも及んだ。','The impact extended beyond the country to overseas.','A geographic expansion.'],['彼の活動は執筆[にとどまらず]教育にも広がる。','His work extends beyond writing into education.','A wider range of activities.'],['被害は家屋[にとどまらず]農地にも出た。','Damage affected not just houses but farmland too.','An expanding set of affected areas.']]),
p('n1-131','Judge a proposal or claim as strained or impractical.','N / plain clause + には無理がある','neutral/formal','Often softens disagreement with a plan or inference.','It critiques feasibility or reasoning, not necessarily physical impossibility.',[
['全員を一台に乗せる[には無理がある]。','Fitting everyone into one vehicle is impractical.','A capacity limitation.'],['その説明[には無理がある]。','That explanation is a stretch.','The reasoning is unconvincing.'],['二日で完成させる[には無理がある]。','Completing it in two days is unrealistic.','A schedule exceeds reasonable limits.']]),
p('n1-132','Disregard a classification or avoid relying on a means.','N + によらず','formal','Context distinguishes regardless of from without relying on.','Do not confuse it with によって, which can identify a determining factor.',[
['年齢[によらず]参加できる。','Anyone may participate regardless of age.','A criterion is excluded.'],['機械[によらず]手作業で仕上げた。','We finished it by hand without relying on machines.','A means is not used.'],['天候[によらず]室内で実施する。','We will hold it indoors regardless of the weather.','The condition does not alter the venue.']]),
p('n1-133','Emphasize repeated accumulation of the same action.','Action noun + に + same noun + を重ねて','formal/emphatic','Often with 苦労, 検討, 失敗, and 練習.','Repeat the noun to show accumulation, rather than list different actions.',[
['検討[に]検討[を重ねて]案を決めた。','We chose the proposal after repeated careful consideration.','Extended deliberation.'],['失敗[に]失敗[を重ねて]技術を学んだ。','I learned the technique through failure after failure.','Repeated setbacks lead to learning.'],['苦労[に]苦労[を重ねて]店を守った。','They kept the shop going through hardship after hardship.','A cumulative struggle.']]),
p('n1-134','Rebuke behavior as exceeding an acceptable limit.','N / な-adjective stem + にもほどがある; plain clause + にもほどがある','critical','Common in direct complaints about excess.','It sounds judgmental, so it is not a neutral degree description.',[
['冗談[にもほどがある]。','There is a limit to joking.','The joke has gone too far.'],['無責任[にもほどがある]発言だ。','That remark is irresponsibility taken too far.','A strong rebuke.'],['人を待たせる[にもほどがある]。','There is a limit to how long you can keep someone waiting.','Criticizes excessive delay.']]),
p('n1-135','Describe a degree as even greater than a comparison point.','N + にも増して','neutral/formal','Often with いつも, 昨年, or 何.','The comparison is an increase in degree, not simply an additional object.',[
['今日はいつも[にも増して]静かだ。','It is even quieter than usual today.','An increased degree of quiet.'],['今年は昨年[にも増して]応募が多い。','There are even more applications this year than last year.','A stronger annual result.'],['何[にも増して]家族の無事がうれしい。','More than anything, I am glad my family is safe.','Places one joy above all others.']]),
p('n1-136','Say that a reaction is unwarranted or unnecessary.','V dictionary + には当たらない','formal','Often with 驚く, 非難する, and 心配する.','This concerns justification, not whether the reaction is physically possible.',[
['この程度で驚く[には当たらない]。','This is not enough to warrant surprise.','The reaction would be excessive.'],['事情を考えれば非難する[には当たらない]。','Considering the circumstances, blame is unwarranted.','Context removes grounds for criticism.'],['数字の差は小さく、心配する[には当たらない]。','The numerical difference is small and no cause for concern.','A measured assessment of a discrepancy.']]),
p('n1-137','Deny the need for an action or deny equality in comparison.','V dictionary + には及ばない; N + には及ばない','formal/neutral','Verb use often reassures; noun use compares ability or quality.','Choose the sense from what precedes には.',[
['わざわざ来る[には及びません]。','There is no need to make a special trip here.','A polite reassurance.'],['礼を言う[には及ばない]。','There is no need to thank me.','Downplays a favor.'],['腕前では師匠[には及ばない]。','My skill does not match my teacher’s.','A comparison of ability.']]),
p('n1-138','Express an intense feeling through a formal fixed phrase.','Emotion noun + の至り','formal/ceremonial','Common with 光栄, 感激, and 赤面.','Not freely attachable to every feeling noun.',[
['お招きにあずかり、光栄[の至り]です。','I am deeply honored to be invited.','A ceremonial expression of honor.'],['お言葉を頂き、感激[の至り]です。','I am profoundly moved by your words.','A formal emotional response.'],['不勉強を指摘され、赤面[の至り]だった。','I was utterly embarrassed to have my lack of study pointed out.','An intense feeling of shame.']]),
p('n1-139','Present a state as the utmost degree of an evaluation.','N + の極み','formal/emphatic','Common with 贅沢, 疲労, and 痛恨.','It is an extreme evaluation, not necessarily a measurable maximum.',[
['静かな宿で過ごすのは贅沢[の極み]だ。','Staying at a quiet inn is the height of luxury.','An emphatic positive evaluation.'],['連日の作業で疲労[の極み]にあった。','After days of work, I was utterly exhausted.','An extreme physical state.'],['確認を怠ったのは痛恨[の極み]だ。','Failing to check is a matter of the deepest regret.','A strong retrospective judgment.']]),
p('n1-140','Exclaim conversationally about an extreme degree.','い-adjective + のなんのって; な-adjective + なのなんのって','colloquial/emotional','Often followed by an explanation of just how extreme it was.','It is an exclamation, not a literal question about what.',[
['坂が急[なのなんのって]、息が切れた。','The slope was so steep that I was out of breath.','A vivid spoken complaint.'],['会場は暑い[のなんのって]、汗だくになった。','The venue was unbelievably hot; I was drenched in sweat.','A physical consequence illustrates degree.'],['新しい犬がかわいい[のなんのって]、写真ばかり撮っている。','The new dog is so adorable that I keep taking photos.','An affectionate exclamation.']]),
p('n1-141','Express uncertainty, puzzlement, or an unknowable amount.','Question clause + のやら / ものやら / ことやら','reflective/colloquial','Question words commonly precede it; ことやら can stress how much.','It often conveys emotion beyond a plain embedded question.',[
['鍵をどこに置いた[のやら]、思い出せない。','Where on earth did I put the key? I cannot remember.','Puzzlement about a location.'],['いつ終わる[ものやら]見当もつかない。','I have no idea when it will ever end.','A weary uncertainty.'],['何度説明した[ことやら]。','Who knows how many times I have explained it.','An exasperated unspecified number.']]),
p('n1-142','Express confusion between two possible states.','Plain clause + のやら … + のやら','conversational/reflective','Often pairs opposing interpretations.','The speaker is unsure which applies; both are not asserted as facts.',[
['賛成[なのやら]反対[なのやら]、返事が曖昧だ。','The reply is vague; I cannot tell whether it is agreement or opposition.','Ambiguous intent.'],['眠っている[のやら]考えている[のやら]分からない。','I cannot tell whether he is sleeping or thinking.','Uncertain observation.'],['便利[なのやら]不便[なのやら]、評価に迷う。','I cannot decide whether it is convenient or inconvenient.','Mixed impressions prevent a judgment.']]),
p('n1-143','Use known facts or earlier results as the basis for a next step.','N + を踏まえて / を踏まえた + N','formal','Often with 経験, 結果, 意見, and 事実.','The next action should actually take account of that basis.',[
['調査結果[を踏まえて]方針を決める。','We will decide the policy based on the survey results.','Evidence informs a decision.'],['前回の反省[を踏まえた]計画だ。','The plan incorporates lessons from last time.','Past shortcomings guide improvement.'],['皆の意見[を踏まえて]文章を直した。','I revised the text taking everyone’s comments into account.','Feedback changes the output.']]),
p('n1-144','Describe passing through stages, time, or places before a result.','N + を経て','formal','Often summarizes a process leading to a new stage.','経て does not itself imply success; the later predicate supplies the outcome.',[
['研修[を経て]現場に配属された。','After training, I was assigned to the site.','A required stage precedes placement.'],['十年[を経て]再会した。','We met again after ten years.','Elapsed time leads to reunion.'],['京都[を経て]神戸へ向かった。','We headed to Kobe via Kyoto.','A route passes through a place.']]),
p('n1-145','Describe a notable event approaching or a location just behind.','N + を控えて / を控えた + N','formal/neutral','Most often used with a forthcoming event.','With a place noun it can instead describe a nearby background location.',[
['試験[を控えて]毎日復習している。','With the exam approaching, I review every day.','An upcoming event shapes preparation.'],['出発[を控えた]朝、雪が降った。','It snowed on the morning just before our departure.','An imminent event frames the scene.'],['背後に山[を控えた]町を訪ねた。','I visited a town with mountains rising behind it.','A spatial background use.']]),
p('n1-146','Exploit a favorable circumstance for selfish behavior.','Plain clause + のをいいことに; N / な-adjective + なのをいいことに','critical','The circumstance makes misconduct easier.','It usually conveys disapproval, not a neutral opportunity.',[
['誰も見ていない[のをいいことに]菓子を全部食べた。','Taking advantage of nobody watching, he ate all the sweets.','Lack of supervision is exploited.'],['留守な[のをいいことに]勝手に部屋を使った。','They took advantage of my absence to use the room without asking.','Someone’s absence enables intrusion.'],['返事がない[のをいいことに]話を進めた。','They used the lack of a reply as an excuse to proceed.','Silence is treated opportunistically.']]),
p('n1-147','Act without regard for a risk, cost, or duty.','N + を顧みず / も顧みず','formal','May praise courage or criticize disregard, depending on the noun.','It means not taking something into account, not merely forgetting it.',[
['危険[も顧みず]救助に向かった。','She went to the rescue without regard for the danger.','A courageous action.'],['自分の生活[を顧みず]研究に没頭した。','He immersed himself in research without regard for his own life.','Dedication carries a personal cost.'],['周囲への影響[を顧みず]工事を進めた。','They continued construction without regard for its effect on neighbors.','A criticized lack of consideration.']]),
p('n1-148','Mark a final endpoint or the fullest available extent.','Time noun + を限りに; 声 / 力 + を限りに','formal/emphatic','Time use marks discontinuation; extent use is limited to suitable nouns.','Do not assume every noun marks a deadline.',[
['今月[を限りに]店を閉めます。','We will close the shop at the end of this month.','A final operating period.'],['今日[を限りに]甘い飲み物をやめる。','As of today, I am giving up sweet drinks.','A declared stopping point.'],['声[を限りに]助けを呼んだ。','I shouted for help at the top of my voice.','The maximum available force.']]),
p('n1-149','Give an action two purposes or combine two roles.','N + を兼ねて; N + と + N + を兼ねて','neutral/formal','The same activity fulfills both purposes.','It describes a genuine combined function, not an invented pretext.',[
['運動[を兼ねて]歩いて通勤する。','I walk to work to get exercise as well.','Travel doubles as exercise.'],['お礼と報告[を兼ねて]手紙を書いた。','I wrote a letter both to thank them and to report back.','Two communicative purposes.'],['案内[を兼ねて]街を一緒に歩いた。','I walked around town with them, also acting as their guide.','One outing includes a guiding role.']]),
p('n1-150','Name the first event in a continuing sequence.','N + を皮切りに（して）','formal/reporting','Usually launches a series of similar events.','The following events should form a sequence, not a single unrelated result.',[
['大阪公演[を皮切りに]全国を巡る。','Starting with the Osaka performance, we will tour the country.','The first stop begins a tour.'],['一号店[を皮切りに]店舗を増やした。','Starting with the first shop, they expanded the chain.','An initial opening begins expansion.'],['春の展示[を皮切りに]企画が続く。','A series of events begins with the spring exhibition.','An opening event starts a program.']]),
p('n1-151','Treat an event as the opportunity for a new development.','N + を機に / を機として','formal/neutral','Often marks a deliberate change following a milestone.','The event is a trigger or opportunity, not necessarily the sole cause.',[
['引っ越し[を機に]自炊を始めた。','I started cooking for myself when I moved.','A life change prompts a habit.'],['退職[を機に]故郷へ戻った。','I returned to my hometown upon retirement.','A milestone enables a move.'],['受賞[を機として]作品が広く知られた。','Winning the award led to the work becoming widely known.','An event changes public recognition.']]),
p('n1-152','Describe an emotion that cannot be held back.','Emotion noun + を禁じ得ない','formal','Common with 驚き, 怒り, 同情, and 涙.','It is an involuntary emotional response, not an explicit ban.',[
['突然の閉館に驚き[を禁じ得ない]。','I cannot help feeling astonished by the sudden closure.','Unexpected news provokes emotion.'],['無責任な対応に怒り[を禁じ得なかった]。','I could not suppress my anger at the irresponsible response.','A strong moral reaction.'],['再会の場面に涙[を禁じ得なかった]。','I could not hold back tears at the reunion.','Emotion becomes visible.']]),
p('n1-153','Show someone overcoming an obstacle without being deterred.','N + をものともせず（に）','formal/emphatic','Usually admires persistence despite a real obstacle.','The obstacle is disregarded as a deterrent, not denied to exist.',[
['強風[をものともせず]選手は走り続けた。','The athlete kept running undeterred by the strong wind.','A physical obstacle is overcome.'],['批判[をものともせずに]改革を進めた。','She pursued reform undeterred by criticism.','Opposition does not stop action.'],['言葉の壁[をものともせず]友達を作った。','He made friends despite the language barrier.','A social obstacle is surmounted.']]),
p('n1-154','Mark a formal endpoint or identify a means.','Time + をもって / をもちまして; N + をもって','formal','をもちまして is especially ceremonial for endings.','The noun determines whether the use concerns time or means.',[
['本日[をもちまして]受付を終了します。','Applications close as of today.','A formal closing announcement.'],['書面[をもって]通知いたします。','We will notify you in writing.','The medium is specified.'],['誠意[をもって]対応する。','We will respond in good faith.','An attitude serves as the manner of response.']]),
p('n1-155','Assert that no alternative surpasses the named choice.','N + をおいて + … ない','formal/emphatic','Usually names the only suitable person, place, or time.','The negative conclusion is essential to the exclusivity.',[
['この役を任せられるのは彼[をおいて]ほかにい[ない]。','No one but him is right for this role.','A uniquely suitable person.'],['始めるなら今[をおいて]機会は[ない]。','If we are to begin, there is no better chance than now.','An irreplaceable opportunity.'],['相談相手は先生[をおいて]考えられ[ない]。','I cannot imagine consulting anyone other than my teacher.','An exclusive source of advice.']]),
p('n1-156','Proceed despite difficulty or press past active opposition.','N + を押して / を押し切って','formal','押して often with illness or inconvenience; 押し切って often with opposition.','押し切る suggests overcoming resistance more strongly.',[
['病気[を押して]式に出席した。','He attended the ceremony despite being ill.','A physical difficulty is accepted.'],['反対[を押し切って]計画を実行した。','She carried out the plan over opposition.','Active resistance is overcome.'],['ご無理[を押して]お願いしました。','I made the request knowing it would inconvenience you.','A polite acknowledgment of burden.']]),
p('n1-157','Identify a boundary after which a situation changes.','N + を境に（して）','neutral/formal','Can refer to a date, event, or physical dividing line.','It marks a contrast across a boundary, not just any starting time.',[
['結婚[を境に]生活が変わった。','My life changed after I got married.','An event divides two life stages.'],['川[を境に]方言が違う。','The dialect changes across the river.','A physical boundary.'],['あの日[を境に]連絡が途絶えた。','Contact stopped from that day onward.','A clear temporal turning point.']]),
p('n1-158','Describe an unwanted change imposed by circumstances.','N + を余儀なくされる','formal/reporting','The subject undergoes a forced change, usually an action noun.','Passive される takes the affected party as subject.',[
['洪水で住民は避難[を余儀なくされた]。','Flooding forced the residents to evacuate.','An external event removes choice.'],['材料不足で生産の縮小[を余儀なくされた]。','Material shortages forced a reduction in production.','A resource constraint imposes a change.'],['けがで選手は引退[を余儀なくされた]。','An injury forced the athlete to retire.','An unwelcome career consequence.']]),
p('n1-159','Contrast ongoing behavior with a concern being ignored.','N + をよそに','written/critical','Often with 心配, 期待, or 騒ぎ.','It does not simply mean being located somewhere else.',[
['親の心配[をよそに]息子は旅を続けた。','Ignoring his parents’ worries, the son continued traveling.','Concern does not alter his behavior.'],['周囲の騒ぎ[をよそに]猫は眠っていた。','The cat slept on, oblivious to the commotion.','A calm action contrasts with its setting.'],['期待[をよそに]発表は延期された。','Despite everyone’s anticipation, the announcement was postponed.','Reality disregards expectations.']]),
p('n1-160','Make an agreement or action rest on an explicit prerequisite.','N + を前提として; clause + ことを前提として','formal','The prerequisite is assumed or required for what follows.','If the prerequisite fails, the arrangement may no longer apply.',[
['参加[を前提として]人数に入れた。','I included you in the count on the assumption that you would attend.','An assumption controls preparation.'],['返却すること[を前提として]貸します。','I will lend it on condition that you return it.','A condition accompanies permission.'],['安全の確保[を前提とした]計画だ。','The plan rests on ensuring safety.','A prerequisite underpins a proposal.']]),
p('n1-161','Describe undergoing an emotionally colored experience.','い-adjective / な-adjective + な + 思いをする','neutral','Typical adjectives describe difficulty, fear, embarrassment, or pleasure.','It describes an experience that gives rise to the feeling, not just an opinion.',[
['暗い道で怖い[思いをした]。','I had a frightening experience on the dark road.','Fear arises from an event.'],['名前を間違えて恥ずかしい[思いをした]。','I felt embarrassed after getting the name wrong.','An incident creates embarrassment.'],['親切にされて、うれしい[思いをした]。','Their kindness gave me a happy experience.','A welcome event creates a pleasant feeling.']]),
p('n1-162','Refer politely or formally to an occasion for doing something.','V dictionary / た + 折に; N + の折に','formal/polite','Often appears in invitations and requests involving future visits.','It is an occasion expression, not necessarily a physical fold.',[
['近くへお越しの[折に]お立ち寄りください。','Please stop by when you are in the area.','A polite invitation tied to an occasion.'],['帰省した[折に]恩師を訪ねた。','I visited my former teacher when I returned home.','An opportunity during a visit.'],['次に会う[折に]本を返します。','I will return the book when we next meet.','An occasion sets the timing.']]),
p('n1-163','Give an approximation or emphasize a broad general judgment.','およそ + quantity; およそ … negative; およそ + general category','neutral/formal','The meaning depends on whether a quantity or judgment follows.','With a negative it can mean entirely, not approximately.',[
['駅までは[およそ]二キロだ。','It is approximately two kilometers to the station.','An approximate measurement.'],['その話は現実とは[およそ]関係がない。','That story has absolutely nothing to do with reality.','A strong negative judgment.'],['[およそ]道具というものは手入れが必要だ。','Tools, generally speaking, require maintenance.','A broad generalization.']]),
p('n1-164','Add a casual, assured tone to a statement.','Plain clause + さ; phrase + さ as conversational filler','colloquial','Often familiar or rough; tone varies with region and speaker.','Avoid this plain ending in formal requests or respectful announcements.',[
['失敗しても、また始めればいい[さ]。','Even if you fail, you can just start again.','A casual reassuring stance.'],['そのくらい自分でできる[さ]。','I can do that much myself.','A confident informal assertion.'],['僕[さ]、明日引っ越すんだ。','You know, I am moving tomorrow.','An inserted conversational particle.']]),
p('n1-165','Describe a conspicuous appearance, sometimes a misleading one.','さも … そうに / ように / げに','neutral/literary','Often suggests that someone acts as though something were true.','Whether the appearance is genuine comes from context.',[
['彼は[さも]知っているかのようにうなずいた。','He nodded as though he knew all about it.','The speaker doubts the apparent knowledge.'],['猫は[さも]満足そうに目を閉じた。','The cat closed its eyes looking thoroughly content.','A strong visible impression.'],['彼女は[さも]残念そうに肩を落とした。','She lowered her shoulders, looking deeply disappointed.','Describes an outward emotional display.']]),
p('n1-166','Warn of what follows if the preceding action is not taken.','Instruction / necessary action + さもないと + consequence','neutral','Usually introduces an unwelcome alternative.','The consequence follows from not complying, not from complying.',[
['早く出よう。[さもないと]最終便に乗れない。','Let’s leave now; otherwise we will miss the last service.','A practical warning.'],['水を足して。[さもないと]焦げるよ。','Add some water, or it will burn.','A needed preventive action.'],['期限までに返事をください。[さもないと]席を確保できません。','Please reply by the deadline; otherwise we cannot hold a seat.','A clear consequence of inaction.']]),
p('n1-167','Imagine the high degree of another person’s feeling.','さぞ + emotion / evaluation + だろう / でしょう / ことだろう','empathetic/formal','Usually an inference from circumstances.','It expresses sympathetic conjecture rather than direct knowledge.',[
['合格して、[さぞ]うれしいでしょう。','You must be delighted to have passed.','Infers another person’s joy.'],['長旅で[さぞ]お疲れでしょう。','You must be very tired after the long journey.','A courteous expression of concern.'],['一人で待つのは[さぞ]心細かっただろう。','Waiting alone must have felt terribly lonely.','Imagines a past emotional state.']]),
p('n1-168','Present a bad final outcome after an unfortunate course of events.','V dictionary + 始末だ','critical/regretful','Usually follows a series of deteriorating actions or failures.','Do not use it for a straightforward positive achievement.',[
['寝坊し、財布も忘れ、切符までなくす[始末だ]。','I overslept, forgot my wallet, and even ended up losing my ticket.','Failures accumulate.'],['彼は遅刻を重ね、会議にも来ない[始末だ]。','He is repeatedly late and now does not even come to meetings.','A worsening pattern.'],['修理を試みたが、部品を壊す[始末だった]。','I tried to repair it but ended up breaking a part.','The attempt makes matters worse.']]),
p('n1-169','Describe an action’s effect being repeatedly undone immediately.','V dictionary / た + そばから','neutral/complaining','Usually a recurring pattern, not one isolated occurrence.','For one immediate event, use a simple time expression instead.',[
['片付ける[そばから]子供が散らかす。','As fast as I tidy up, the children make a mess again.','Work is repeatedly undone.'],['覚えた[そばから]単語を忘れてしまう。','I forget words almost as soon as I learn them.','A recurring frustrating cycle.'],['窓を拭く[そばから]雨粒が付く。','Raindrops keep landing as soon as I wipe the window.','The clean state does not last.']]),
p('n1-170','Miss the opportunity to carry out an intended action.','Vます stem + そびれる','neutral','The action is left undone because the timing was missed.','It is not simply failing despite a completed attempt.',[
['話しかける機会を待って、言い[そびれた]。','I waited for a chance to speak and missed saying it.','Waiting causes a missed opening.'],['忙しくて昼ご飯を食べ[そびれた]。','I was busy and missed lunch.','A suitable time passes.'],['改札で手を振り[そびれた]。','I missed the chance to wave at the ticket gate.','A brief opportunity is lost.']]),
p('n1-171','Fail to complete an action or perform it incorrectly.','Vます stem + 損なう / 損ねる / 損じる','neutral; 損じる formal','Can mean missing an opportunity or making an error, depending on the verb.','The object and verb determine whether the action was missed or mishandled.',[
['大事な番号を聞き[損ねた]。','I missed hearing the important number.','Information is not caught.'],['宛名を書き[損じた]。','I wrote the address incorrectly.','An action is performed wrongly.'],['最後の一球を取り[損なった]。','I failed to catch the final ball.','An attempted action fails.']]),
p('n1-172','Say that no available method can achieve a goal.','V dictionary + 術がない','formal/reflective','術 is read すべ; it concerns means or methods.','It is not the skill noun じゅつ in this expression.',[
['連絡先がなく、確かめる[術がない]。','I have no contact information and no way to check.','No usable means of verification.'],['消えた記録を戻す[術がない]。','There is no way to restore the deleted records.','A recovery method is unavailable.'],['その場では身を守る[術がなかった]。','At that moment, I had no means of protecting myself.','A lack of practical options.']]),
p('n1-173','Emphasize an extreme example, often a minimum that fails.','N + すら / ですら; particle + すら','formal/emphatic','Often similar to さえ; frequently appears with negatives.','It is stronger than the ordinary additive も.',[
['自分の住所[すら]思い出せなかった。','I could not even remember my own address.','A basic fact is inaccessible.'],['専門家[ですら]答えに迷った。','Even the experts hesitated over the answer.','An unexpected group struggles.'],['忙しくて水を飲む時間[すら]ない。','I am so busy I do not even have time to drink water.','A minimal opportunity is missing.']]),
p('n1-174','Connect a physical action or sudden moment to an accidental result.','Vた + 弾みに / 拍子に','neutral','Often describes unintended movement or something forgotten in a moment.','Do not use it as a general reason for a deliberate long-term decision.',[
['転んだ[拍子に]眼鏡が外れた。','My glasses came off when I fell.','A sudden impact causes an accident.'],['立ち上がった[弾みに]コップを倒した。','I knocked over a glass as I stood up.','Movement has an unintended result.'],['驚いた[拍子に]持っていた紙を落とした。','In my surprise, I dropped the paper I was holding.','A momentary reaction causes a mishap.']]),
p('n1-175','Treat an event as having occurred, or state the resulting interpretation.','Vた + ことにする / ことになる','neutral','ことにする is a choice; ことになる describes a consequence or reckoning.','Do not confuse this past-event treatment with deciding a future action.',[
['聞かなかった[ことにする]。','I will pretend I did not hear that.','The speaker chooses how to treat an event.'],['今日は来た[ことにして]おきましょう。','Let’s count you as having attended today.','A deliberately adopted record.'],['これで二回払った[ことになる]。','That means I have paid twice.','A result follows from the facts.']]),
p('n1-176','Judge a hypothetical effort as unable to change the result.','Vた + ところで + limited / negative result','neutral','Often expresses futility.','This is concessive, unlike Vたところ describing what actually happened.',[
['今から走った[ところで]間に合わない。','Even if we run now, we will not make it.','Effort comes too late.'],['私に聞いた[ところで]答えは出ない。','Even if you ask me, you will not get an answer.','The proposed source cannot help.'],['値段を下げた[ところで]売れるとは限らない。','Even lowering the price will not necessarily make it sell.','A change does not guarantee success.']]),
p('n1-177','Deny having intended or regarded a past action in a certain way.','Vた + つもりはない','neutral/defensive','Common when the listener interprets an action differently.','It denies intention or self-assessment, not necessarily the observable act.',[
['君を責めた[つもりはない]。','I did not mean to blame you.','Intention differs from perceived effect.'],['約束を忘れた[つもりはない]。','I do not consider myself to have forgotten the promise.','A denial of the interpretation.'],['冗談を言った[つもりはない]。','I was not trying to make a joke.','The speaker insists on seriousness.']]),
p('n1-178','Limit the available response to one remaining action.','ただ + V dictionary + のみだ','formal/solemn','Often expresses resolve, waiting, or a lack of further options.','Do not use the noun-only だけ form inside this verb construction.',[
['今は[ただ]無事を祈る[のみだ]。','For now, all we can do is pray for their safety.','No practical action remains.'],['準備は終わった。[ただ]出発を待つ[のみだ]。','Preparation is complete; all that remains is to await departure.','One final step remains.'],['目標に向かって[ただ]進む[のみだ]。','We can only keep moving toward our goal.','A solemn statement of resolve.']]),
p('n1-179','Emphasize that something has never happened in one’s experience.','Vた + ためしがない','neutral/critical','Often expresses a strong judgment about a repeated pattern.','It describes past experience, not a logical impossibility.',[
['彼が時間を守った[ためしがない]。','He has never once been on time.','A critical generalization from experience.'],['この方法で失敗した[ためしがない]。','This method has never failed me.','Confidence based on experience.'],['あの店で嫌な思いをした[ためしがない]。','I have never had a bad experience at that shop.','A positive record of past visits.']]),
p('n1-180','Warn that once an action occurs, a bad consequence is inevitable.','Vたら + 最後; Vた + が最後','emphatic','Typically introduces an irreversible or hard-to-stop consequence.','最後 is not the last occurrence in a sequence here.',[
['秘密を話し[たら最後]、町中に広まる。','Once you tell that secret, the whole town will know.','Disclosure cannot be undone.'],['この椅子に座っ[たが最後]、眠ってしまう。','Once I sit in this chair, I inevitably fall asleep.','An exaggerated inevitable result.'],['その話を始め[たら最後]、一時間は終わらない。','Once he starts that story, it will not end for an hour.','A hard-to-stop consequence.']]),
p('n1-181','Acknowledge that a changed condition brings its own issues or response.','Vたら + same Vたで; adjective conditional + repeated adjective + で','neutral','Often contrasts the problems of having something with those of lacking it.','Repeat the relevant condition; it is not a simple single たら conditional.',[
['車を買っ[たら]買っ[たで]、維持費がかかる。','If I buy a car, owning it will bring maintenance costs.','A solution creates a different burden.'],['人が集まっ[たら]集まっ[たで]、場所が足りない。','If people do come, then we will lack space.','The alternative has its own problem.'],['安けれ[ば]安い[で]、品質が気になる。','If it is cheap, then I worry about the quality.','Either price level can cause concern.']]),
p('n1-182','Imagine what would be happening if past circumstances had differed.','Counterfactual たら / ば + Vている / V dictionary + ところだ','reflective','The imagined scene contrasts with the actual present or past.','Give enough context to make the unreal condition clear.',[
['列車に乗れてい[たら]、今ごろ海を見ている[ところだ]。','If I had caught the train, I would be looking at the sea by now.','An unreal present scene.'],['休みが取れてい[たら]、今は山を歩いている[ところだ]。','If I had managed to get leave, I would be hiking now.','A missed holiday changes the present.'],['鍵が見つからなかっ[たら]、外で待っている[ところだった]。','If I had not found the key, I would have been waiting outside.','An avoided alternative situation.']]),
p('n1-183','Exclude even the smallest amount from permission or neglect.','Minimal quantity + たりとも + negative','formal/emphatic','Often with 一人, 一秒, or 一円.','A negative or prohibitive conclusion normally follows.',[
['一秒[たりとも]無駄にできない。','We cannot waste even a second.','An absolute minimum of time.'],['一人[たりとも]置き去りにしない。','We will not leave even one person behind.','An inclusive commitment.'],['一円[たりとも]余計に払いたくない。','I do not want to pay even one yen extra.','A minimal amount is excluded.']]),
p('n1-184','Demand conduct appropriate to an important role.','Role noun + たるもの; N + たる + N','formal/solemn','Often introduces a duty or ethical standard.','It can sound prescriptive or old-fashioned in casual advice.',[
['指導者[たるもの]、責任を引き受けるべきだ。','A leader should accept responsibility.','A role entails obligations.'],['教育者[たるもの]、学び続けねばならない。','An educator must keep learning.','A continuing professional standard.'],['代表[たる]立場を忘れてはならない。','You must not forget your position as a representative.','たる links an identity to a noun.']]),
p('n1-185','Complain that a sensation or condition is too strong to bear.','い-adjective くて / な-adjective で / Vて + かなわない','colloquial','Often used for heat, noise, pain, or inconvenience.','This かなわない is not a comparison of ability with an opponent.',[
['隣の工事がうるさく[てかなわない]。','The construction next door is unbearably noisy.','An ongoing nuisance.'],['部屋が暑く[てかなわない]。','The room is unbearably hot.','A strong physical discomfort.'],['靴がきつく[てかなわない]。','These shoes are painfully tight.','A condition feels intolerable.']]),
p('n1-186','Describe a sustained change beginning with a particular event.','Vて + からというもの','emphatic/narrative','The later state continues or recurs from that turning point.','Use a sustained consequence, not an unrelated one-time event.',[
['犬を飼っ[てからというもの]、毎朝散歩している。','Ever since I got a dog, I have walked every morning.','A new recurring habit.'],['引っ越し[てからというもの]、よく眠れる。','Ever since moving, I have been sleeping well.','A continuing improvement.'],['あの本を読ん[でからというもの]、星を見るのが楽しみだ。','Ever since reading that book, I have enjoyed watching the stars.','An event changes an enduring interest.']]),
p('n1-187','Demonstrate an action or declare determination to achieve it.','Vて + みせる','neutral/emphatic','Literal demonstration and determined promise are distinct uses.','It is not the tentative trial meaning of てみる.',[
['先生は折り方をやっ[てみせた]。','The teacher demonstrated how to fold it.','An action is shown to learners.'],['次こそ合格し[てみせる]。','I will pass next time, you will see.','A determined personal promise.'],['壊れた時計を必ず直し[てみせる]。','I will definitely fix the broken clock.','The speaker promises to prove capability.']]),
p('n1-188','Judge an action or treatment as what is properly expected.','Vて + しかるべきだ','formal','Often appeals to fairness, duty, or a natural standard.','It is a normative judgment, not a prediction that the action will occur.',[
['被害を受けた人には説明し[てしかるべきだ]。','Those affected ought properly to receive an explanation.','A duty to explain.'],['功績はもっと評価され[てしかるべきだ]。','The achievement deserves greater recognition.','A judgment about fair treatment.'],['変更するなら事前に知らせ[てしかるべきだ]。','If making a change, you should give advance notice.','A reasonable procedural expectation.']]),
p('n1-189','Say that an easy response cannot settle a serious matter.','Vて + 済むことではない','neutral/emphatic','Often criticizes an apology or replacement as inadequate.','The preceding action is the insufficient remedy.',[
['謝っ[て済むことではない]。','This is not something an apology can settle.','Further accountability remains.'],['壊れた物を買い替え[て済むことではない]。','Simply replacing what was broken will not put this right.','The harm goes beyond the object.'],['担当者を替え[て済むことではない]。','Changing the person in charge will not resolve this.','The issue is systemic.']]),
p('n1-190','Express a deep and continuing wish or feeling.','Vて + やまない','formal/ceremonial','Usually with 願う, 祈る, 愛する, or 尊敬する.','It describes sustained feeling, not an action repeatedly attempted.',[
['皆様の健康を願っ[てやみません]。','I sincerely wish you all good health.','A formal enduring wish.'],['故郷を愛し[てやまない]。','I have an abiding love for my hometown.','A continuing affection.'],['研究の成功を祈っ[てやまない]。','I earnestly hope for the research to succeed.','A solemn expression of hope.']]),
p('n1-191','Explain an obligation created by appearances or a prior statement.','Vた / N + の + 手前','neutral/formal','Social consistency or someone’s presence constrains the choice.','It does not mean physical space in front of something here.',[
['約束した[手前]、断れない。','Having promised, I cannot refuse now.','A prior commitment creates pressure.'],['子供の[手前]、弱音は吐けなかった。','I could not complain in front of the children.','Concern for one’s example shapes behavior.'],['自分で提案した[手前]、最後まで担当する。','Since I proposed it myself, I will see it through.','Responsibility follows a public position.']]),
p('n1-192','Dismiss an action as unable to improve the situation.','Vて + もどうにもならない','neutral/resigned','The action cannot change the relevant result.','This is practical futility, not necessarily inability to perform the action.',[
['今さら悔やん[でもどうにもならない]。','Regretting it now will not change anything.','A past result cannot be undone.'],['ここで待っ[てもどうにもならない]。','Waiting here will do no good.','The action cannot solve the problem.'],['私一人が騒い[でもどうにもならない]。','My making a fuss alone will not change anything.','Limited influence makes the action futile.']]),
p('n1-193','Give formal permission or state that something poses no problem.','Vて + も差し支えない','formal/polite','Often used in procedural permission and requests for information.','It grants permission rather than recommending the action.',[
['この席を使っ[ても差し支えありません]。','You may use this seat.','A formal permission.'],['名前を公表し[ても差し支えない]。','There is no objection to publishing the name.','A disclosure is permitted.'],['明日提出し[ても差し支えない]でしょうか。','Would it be acceptable to submit it tomorrow?','A polite permission request.']]),
p('n1-194','Warn that someone must accept an unwelcome consequence.','Vて + も知らない（よ）','colloquial/warning','The speaker disclaims responsibility for a foreseeable result.','It is stronger and less polite than simply offering advice.',[
['そんなに走ると、転ん[でも知らないよ]。','If you run like that and fall, do not say I did not warn you.','A familiar warning.'],['保存しないと、消え[ても知らないよ]。','If you do not save it and it disappears, you were warned.','Responsibility is left with the listener.'],['薄着で出ると、風邪を引い[ても知らないよ]。','Go out dressed that lightly and catch a cold, and do not blame me.','A pointed consequence warning.']]),
p('n1-195','Describe two factors combining to create a stronger effect.','N + と相まって; N + が相まって','formal','Both factors contribute jointly to the result.','It implies interaction or reinforcement, not an unrelated list.',[
['照明が音楽[と相まって]幻想的な空間を作った。','The lighting combined with the music to create a dreamlike space.','Two effects reinforce each other.'],['努力が才能[と相まって]成果につながった。','Effort combined with talent to produce results.','Complementary strengths.'],['海風と木陰[が相まって]庭は涼しい。','The sea breeze and shade together keep the garden cool.','Joint environmental effects.']]),
p('n1-196','Make a special case compelling enough to justify an action.','N / plain clause + とあれば','formal/emphatic','Often expresses willingness or necessity under a notable condition.','It is conditional; the special situation need not already be confirmed.',[
['友人の頼み[とあれば]断れない。','If it is a request from a friend, I cannot refuse.','A relationship makes the condition compelling.'],['必要[とあれば]何度でも説明する。','If necessary, I will explain as many times as it takes.','A strong willingness under a condition.'],['子供が困っている[とあれば]放っておけない。','If a child is in trouble, I cannot ignore it.','A compelling reason to intervene.']]),
p('n1-197','Explain an expected response to a notable circumstance.','N / plain clause + とあって','formal/reporting','The circumstance is presented as true and explanatory.','Unlike とあれば, it normally explains an actual situation.',[
['無料[とあって]、会場は満員だった。','Since admission was free, the venue was packed.','A salient fact explains turnout.'],['初雪[とあって]、子供たちは大喜びだ。','It is the first snow, so the children are delighted.','A special event explains emotion.'],['有名な作家が来る[とあって]、長い列ができた。','With a famous writer coming, a long line formed.','A notable visit attracts people.']]),
p('n1-198','Read an unspoken message from someone’s gesture or behavior.','Quoted / implied clause + とばかりに','literary/narrative','The person need not actually say the implied words.','It interprets an attitude, rather than reporting a verbatim quotation.',[
['彼は任せろ[とばかりに]胸をたたいた。','He tapped his chest as if to say, “Leave it to me.”','A gesture conveys confidence.'],['犬は早く行こう[とばかりに]戸を引っかいた。','The dog scratched the door as if to say, “Let’s go already.”','Behavior is interpreted as a message.'],['彼女はこれで終わりだ[とばかりに]本を閉じた。','She closed the book as if to say that was the end.','An action signals finality.']]),
p('n1-199','Maintain a judgment even for a supposedly exceptional case.','N / plain clause + といえども','formal','Often with たとえ or an authority/status noun.','It is concessive, not simply a quotation with 言う.',[
['専門家[といえども]間違うことはある。','Even experts sometimes make mistakes.','Expertise does not remove human limits.'],['子供[といえども]意見を持っている。','Even children have opinions of their own.','Rejects an assumed exception.'],['少額[といえども]無駄にはできない。','Even a small amount must not be wasted.','The principle holds at a small scale.']]),
p('n1-200','Allow a description while keeping some reservations.','Plain clause + と言えなくもない','cautious/formal','The double negative expresses qualified agreement.','It is weaker than an unreserved と言える.',[
['この結果は成功[と言えなくもない]。','This result could, in a sense, be called a success.','A guarded positive evaluation.'],['少し変わった趣味だ[と言えなくもない]。','You could say it is a slightly unusual hobby.','Allows a description cautiously.'],['便利になった[と言えなくもない]が、操作は複雑だ。','It may be more convenient, but it is complicated to use.','A concession precedes a reservation.']]),
p('n1-201','Evaluate a whole through two representative features.','N + といい + N + といい','neutral/emphatic','The paired features typically support the same overall judgment.','Unlike といわず, this emphasizes chosen features rather than every part.',[
['色[といい]形[といい]、この器は美しい。','In both color and shape, this bowl is beautiful.','Representative qualities support praise.'],['味[といい]香り[といい]、申し分ない。','Both the taste and aroma are flawless.','Two sensory qualities are evaluated.'],['態度[といい]言葉遣い[といい]、失礼だ。','His manner and language alike are rude.','Can also support criticism.']]),
p('n1-202','Express an extreme feeling or quality conversationally.','Adjective / N + といったらない','emotional','Often used with feelings, tiredness, or degree evaluations.','It is an idiomatic exclamation, not an actual conditional statement.',[
['山頂からの眺めは美しい[といったらない]。','The view from the summit is indescribably beautiful.','An intense visual impression.'],['返事を待つ間の不安[といったらない]。','The anxiety while waiting for the reply was unbearable.','An emotion is emphasized.'],['一人で全部運ぶのは大変[といったらない]。','Carrying it all alone is incredibly hard.','An emphatic assessment of burden.']]),
p('n1-203','Include every member of a named category emphatically.','N + という + same N','literary/emphatic','The noun is repeated; this is different from naming something with という.','Do not omit the repeated noun or interpret this as a reported quotation.',[
['畑[という]畑が雪に覆われた。','Every field was covered in snow.','The statement includes all fields.'],['棚[という]棚に資料が詰まっている。','Every shelf is packed with documents.','A complete category is filled.'],['道[という]道を探したが、犬はいなかった。','We searched every road, but the dog was nowhere to be found.','Emphasizes an exhaustive search.']]),
p('n1-204','Search for a description by offering two imperfect labels.','Plain expression + というか … + というか','colloquial/reflective','Often followed by a summarizing evaluation.','This paired use signals difficulty describing something, not necessarily a correction.',[
['不思議[というか]不気味[というか]、妙な音だった。','It was a strange sound, mysterious or perhaps eerie.','Two labels approximate an impression.'],['慎重[というか]臆病[というか]、彼は動かなかった。','Cautious or perhaps timid, he did not move.','The evaluation remains unsettled.'],['うれしい[というか]ほっとした[というか]、涙が出た。','Happy or perhaps relieved, I began to cry.','Mixed feelings resist a single label.']]),
p('n1-205','Emphasize that a state has continued throughout a span.','Time-span noun + というもの','emphatic/narrative','Often with この or ここ to mark a period up to now.','This is a duration use, distinct from というものだ for a judgment.',[
['この三日[というもの]、雨が降り続いている。','It has been raining continuously for these past three days.','An uninterrupted recent span.'],['ここ半年[というもの]、毎朝日記を付けている。','For the past six months, I have kept a diary every morning.','A habit persists over a period.'],['この一時間[というもの]、電話が鳴りっぱなしだ。','The phone has been ringing constantly for the past hour.','Emphasizes sustained interruption.']]),
p('n1-206','Give a rough estimate or characterize a result as modest.','Quantity / description + というところだ / といったところだ','neutral','Often sets an approximate level or upper limit.','It is a loose assessment, not an exact measurement.',[
['参加者は二十人[といったところだ]。','There are about twenty participants.','A rough headcount.'],['完成度は七割[というところだ]。','It is roughly seventy percent complete.','An approximate progress estimate.'],['歩いて十五分[といったところです]。','It is about a fifteen-minute walk.','An informal distance-in-time estimate.']]),
p('n1-207','Draw out a conclusion that follows from an explanation.','Plain clause + というわけだ','neutral','Often summarizes the logic behind a situation.','The conclusion should follow from supplied or understood facts.',[
['往復で千円、二人なら二千円[というわけだ]。','It is a thousand yen return, so that makes two thousand for two people.','An explicit calculation.'],['鍵は彼が持っている。つまり、彼を待つしかない[というわけだ]。','He has the key, so we have no choice but to wait for him.','A practical conclusion.'],['原料が減ったので、値段が上がった[というわけだ]。','So the price rose because the raw material supply fell.','Explains the logic of an outcome.']]),
p('n1-208','Reject a generalization without necessarily denying every case.','Plain clause + というわけではない','neutral','Often narrows an inference, cause, or degree.','It usually means not necessarily, rather than a complete opposite.',[
['高ければ長持ちする[というわけではない]。','A high price does not necessarily mean it will last.','Rejects an automatic inference.'],['嫌いだ[というわけではない]が、毎日は食べない。','It is not that I dislike it, but I do not eat it every day.','Denies one interpretation of behavior.'],['全員が賛成した[というわけではない]。','It is not the case that everyone agreed.','Some may have agreed.']]),
p('n1-209','Extend a description to every part by naming representative parts.','N + といわず + N + といわず','emphatic','Typically followed by a condition covering the whole.','Unlike といい, this strongly suggests everywhere or throughout.',[
['床[といわず]壁[といわず]、泥が付いていた。','There was mud everywhere, on the floor, the walls, and all.','Named surfaces imply the whole area.'],['手[といわず]顔[といわず]、絵の具だらけだ。','There is paint all over my hands, face, and everywhere else.','The mess is comprehensive.'],['昼[といわず]夜[といわず]電話が来る。','Calls come at all hours, day and night.','Representative times imply continual occurrence.']]),
p('n1-210','Pile an additional characteristic onto an evaluation, often a complaint.','N / plain clause + ときている','colloquial/evaluative','Often follows other reasons in a cumulative judgment.','It does not literally describe someone arriving.',[
['この部屋は狭い上に、暗い[ときている]。','This room is small and, on top of that, dark.','Adds another drawback.'],['彼は遅刻が多く、謝りもしない[ときている]。','He is often late and, what is more, never even apologizes.','A complaint becomes stronger.'],['軽くて丈夫で、値段も安い[ときている]。','It is light, sturdy, and even cheap.','Can also accumulate praise.']]),
p('n1-211','Show a response made as soon as someone assesses a situation.','Plain clause + とみると','narrative/neutral','Often describes a characteristic reaction whenever the judgment is made.','The judgment belongs to the actor; it is not simply the narrator’s inference.',[
['店主は客が寒そうだ[とみると]暖房を強めた。','Noticing that the customer looked cold, the shopkeeper turned up the heat.','An assessment triggers a response.'],['彼は分が悪い[とみると]話題を変える。','Whenever he sees he is at a disadvantage, he changes the subject.','A habitual reaction to a judgment.'],['鳥は安全だ[とみると]餌に近づく。','Once the bird judges it safe, it approaches the food.','Perceived safety permits action.']]),
p('n1-212','Narrate a swift action upon noticing or judging a situation.','Plain clause + と見るや','written/narrative','Closely related to とみると, with a vivid immediate response.','It describes an observed sequence, not an instruction for the future.',[
['猫は扉が開いた[と見るや]外へ飛び出した。','The instant the cat saw the door open, it darted outside.','A sudden observed reaction.'],['監督は雨が強まった[と見るや]練習を中止した。','As soon as the coach saw the rain intensify, she stopped practice.','A quick decision follows observation.'],['彼は相手がひるんだ[と見るや]前に出た。','Seeing his opponent hesitate, he immediately stepped forward.','A tactical response to a sign.']]),
p('n1-213','Consider the consequences once a situation becomes real or definite.','N / plain clause + となると / となれば / となったら','neutral','Often contrasts a general idea with its practical implementation.','It foregrounds a newly relevant situation, not just any condition.',[
['移住する[となると]準備が多い。','If we are actually going to relocate, there is much to prepare.','An idea becomes a practical plan.'],['全員参加[となれば]広い会場が必要だ。','If everyone is attending, we will need a large venue.','A definite condition creates a requirement.'],['自分が発表する[となったら]急に緊張した。','Once it came to giving the presentation myself, I suddenly got nervous.','Personal involvement changes the response.']]),
p('n1-214','Report a generally accepted view without naming its holder.','Plain clause + とされる / とされている','formal/reporting','Often introduces scholarly or institutional assessments.','It attributes a view; it does not independently prove it.',[
['この橋は国内最古[とされている]。','This bridge is considered the oldest in the country.','An established classification.'],['原因は電気系統の故障だ[とされる]。','The cause is thought to be an electrical failure.','A reported assessment.'],['この地域では春が最適な季節だ[とされている]。','Spring is considered the best season in this area.','A generally held evaluation.']]),
p('n1-215','Bring up a familiar target for an exasperated comment.','N + ときたら','colloquial/critical','Usually introduces a complaint or an emotional assessment.','It can sound rude when used directly about another person.',[
['うちの犬[ときたら]、また靴を隠した。','That dog of ours has hidden my shoes again.','Affectionate exasperation.'],['この端末[ときたら]、すぐ電源が切れる。','This device keeps switching itself off.','A familiar nuisance is introduced.'],['弟[ときたら]、頼んだ物を全部忘れた。','My little brother forgot every single thing I asked for.','A complaint about someone close.']]),
p('n1-216','Acknowledge someone’s circumstances when interrupting or receiving help.','Vている / adjective / N + の + ところを','polite','Often with お忙しい, お休み, or a difficult situation.','The following action intrudes on or responds to that circumstance.',[
['お忙しい[ところを]来てくださり、ありがとうございます。','Thank you for coming despite being busy.','Acknowledges the effort of a visit.'],['お休みの[ところを]失礼します。','I am sorry to disturb you while you are resting.','A polite interruption.'],['困っていた[ところを]助けていただいた。','They helped me when I was in difficulty.','Help arrives in a vulnerable situation.']]),
p('n1-217','Reproach someone whose status should prevent their behavior.','High-status / responsible role + ともあろうものが','formal/critical','Conveys a strong unmet expectation tied to a role.','It is accusatory; do not use it for a neutral identity description.',[
['責任者[ともあろうものが]記録を隠した。','Someone in charge, of all people, concealed the records.','Responsibility heightens the criticism.'],['教師[ともあろうものが]生徒を嘲笑した。','A teacher, of all people, mocked a student.','The act violates a role’s standard.'],['医師[ともあろうものが]確認を怠った。','A doctor, of all people, failed to check.','Professional status makes the lapse worse.']]),
p('n1-218','Describe an action without deliberate focus, or an unidentified source.','V dictionary + ともなく / ともなしに; question word + ともなく','reflective/narrative','Common with 見る, 聞く, and どこから.','It does not simply negate an intentional action; it removes conscious direction.',[
['窓の外を見る[ともなく]見ていた。','I was gazing absently out the window.','Looking without a particular target.'],['ラジオを聞く[ともなしに]聞いていた。','I was listening to the radio without paying much attention.','An unfocused background activity.'],['どこから[ともなく]花の香りがした。','The scent of flowers drifted in from somewhere.','The source is unidentified.']]),
p('n1-219','Warn of an undesirable tendency that can arise without care.','ともすれば + tendency / negative outcome','formal','Often accompanied by がち or かねない.','It describes a risk or inclination, not a certain repeated event.',[
['人は[ともすれば]慣れた方法に頼りがちだ。','People are apt to rely on familiar methods.','An easy tendency to slip into.'],['議論は[ともすれば]感情的になりかねない。','The discussion could easily become emotional.','A risk calls for care.'],['忙しいと[ともすれば]確認を忘れる。','When busy, we are liable to forget to check.','An undesirable lapse becomes likely.']]),
p('n1-220','Decline to choose between two possible descriptions.','Plain expression + とも … + とも + 言えない / つかない','neutral/reflective','Usually pairs alternative or opposing labels.','The negative predicate withholds judgment; it does not affirm both labels.',[
['賛成[とも]反対[とも]言えない。','I cannot say whether I agree or disagree.','Withholds a stance.'],['彼は笑う[とも]泣く[とも]つかない声を出した。','He made a sound that was neither clearly laughter nor crying.','An ambiguous observable quality.'],['成功[とも]失敗[とも]判断できない結果だ。','The result cannot clearly be judged a success or a failure.','The evidence resists either label.']]),
p('n1-221','Select one especially notable item from a larger set.','とりわけ + highlighted item / quality','neutral/formal','Similar to 特に, often with an explicit comparison set.','It does not exclude the importance of the other items.',[
['この町は春が[とりわけ]美しい。','This town is especially beautiful in spring.','One season stands out.'],['参加者の中でも彼女は[とりわけ]熱心だ。','She is particularly enthusiastic among the participants.','A group supplies the comparison.'],['旅では[とりわけ]市場が印象に残った。','The market stood out especially strongly from the trip.','One experience is singled out.']]),
p('n1-222','Express surprise that a normally reliable person made an error.','Person + としたことが','emotional/colloquial','Often self-directed with 私 or 僕.','The following act should conflict with normal expectations of that person.',[
['私[としたことが]鍵を忘れた。','Of all people, I went and forgot my key.','Surprise at one’s own lapse.'],['慎重な彼[としたことが]確認を飛ばした。','Careful as he is, he skipped the check.','The mistake contradicts his usual care.'],['先生[としたことが]日時を間違えた。','Even our teacher got the date and time wrong.','Unexpected error by a trusted person.']]),
p('n1-223','Describe an instinctive response in a sudden moment.','とっさに + quick action / realization','neutral','Often involves little time for deliberate thought.','It is more immediate and reflexive than ordinary すぐに.',[
['物音に驚き、[とっさに]振り向いた。','Startled by a noise, I instinctively turned around.','A sudden sensory response.'],['落ちる皿を[とっさに]受け止めた。','I caught the falling plate in a split second.','A reflex prevents an accident.'],['質問され、[とっさに]答えが出なかった。','When asked, I could not come up with an answer on the spot.','A moment allows no preparation.']]),
p('n1-224','Concede an exceptional case or emphasize even a minimum.','N / plain expression + とて','literary/old-fashioned','Modern formal use often resembles でも or といえども.','Its literary tone makes it unsuitable as a routine replacement for ても.',[
['王[とて]法を逃れることはできない。','Even a king cannot escape the law.','Status does not create an exception.'],['一日[とて]忘れたことはない。','I have not forgotten it for even a single day.','A minimum unit is denied.'],['今さら悔やんだ[とて]戻るものではない。','Even if we regret it now, it will not return.','A literary concessive clause.']]),
p('n1-225','React to an unexpected fact with surprise or strong feeling.','Plain clause / N（だ / だった）+ とは','emotional','The emotional conclusion can be spoken or left implicit.','This entry emphasizes surprise; definition-making とは is a separate use.',[
['こんな所で再会する[とは]驚いた。','I was surprised to meet you again in a place like this.','An unexpected encounter.'],['あの小さな苗がここまで育つ[とは]。','To think that tiny seedling would grow this much!','The feeling is left implicit.'],['まだ十歳だ[とは]信じられない。','I cannot believe they are only ten.','A surprising fact prompts disbelief.']]),
p('n1-226','Acknowledge a fact before adding a qualification.','Plain clause + とはいえ; sentence + とはいえ','formal/neutral','The second clause limits what follows from the first.','It does not necessarily deny that the first fact is true.',[
['春[とはいえ]、朝はまだ冷える。','Although it is spring, mornings are still cold.','A season does not guarantee warmth.'],['完成した[とはいえ]、確認は必要だ。','Although it is finished, it still needs checking.','Completion does not remove another step.'],['便利だ。[とはいえ]、費用が高い。','It is convenient. Even so, it is expensive.','A sentence-level qualification.']]),
p('n1-227','Emphasize a gap too large for a normal comparison.','N + とは比べものにならない','neutral/emphatic','Context should make the direction of the difference clear.','The phrase alone does not specify whether the new thing is better or worse.',[
['新型は旧型[とは比べものにならない]ほど速い。','The new model is incomparably faster than the old one.','The adjective clarifies the direction.'],['山頂の寒さは街[とは比べものにならない]。','The cold at the summit is nothing like the cold in town.','The summit is far colder.'],['手作業の手間は機械[とは比べものにならない]。','The effort of doing it by hand is vastly greater than using a machine.','The context establishes a greater burden.']]),
p('n1-228','Show a striking change from a previous state.','N + とは打って変わって / とは打って変わり','neutral/written','Often contrasts weather, behavior, or mood across time.','Use it for a marked reversal, rather than a tiny adjustment.',[
['昨日[とは打って変わって]快晴だ。','In stark contrast to yesterday, the sky is perfectly clear.','A marked weather change.'],['昼の静けさ[とは打って変わり]、夜はにぎやかだ。','In contrast to its daytime quiet, the place is lively at night.','Different daily phases.'],['以前の態度[とは打って変わって]親切になった。','In a complete change from before, he became helpful.','A reversal in behavior.']]),
p('n1-229','Describe two opposite actions alternating or interacting.','Vます stem + つ + contrasting Vます stem + つ','literary/fixed','Common pairs include 行きつ戻りつ and 持ちつ持たれつ.','Use established contrasting pairs rather than arbitrary verb lists.',[
['行き[つ]戻り[つ]しながら道を探した。','I searched for the route, going back and forth.','Alternating directions.'],['彼とは持ち[つ]持たれ[つ]の関係だ。','He and I have a mutually supportive relationship.','Support flows in both directions.'],['選手は抜き[つ]抜かれ[つ]走った。','The runners kept overtaking one another.','Positions alternate in a race.']]),
p('n1-230','Carry an action through until its object is exhausted.','Vます stem + 尽くす','neutral/emphatic','Works with actions that can cover a complete set or extent.','It implies thorough completion, not simply doing something often.',[
['問題点を話し[尽くした]。','We discussed every aspect of the problems.','Nothing relevant remains to discuss.'],['食料を使い[尽くして]しまった。','We used up all the food.','The resource is exhausted.'],['あの作家の本は読み[尽くした]。','I have read all of that author’s books.','A complete body of work is covered.']]),
p('n1-231','Insist on a repeated message or address someone with exasperation.','Plain clause + ってば / ったら; person + ったら','colloquial','Usually familiar and emotional.','It can sound pushy; avoid it as a polite reminder to a stranger.',[
['もう分かった[ってば]。','I said I understand already.','Insists that a message was heard.'],['触らないで[ったら]。','I told you not to touch it.','A repeated prohibition.'],['お父さん[ったら]、また眼鏡を探している。','Dad is looking for his glasses again, honestly.','Affectionate exasperation about someone.']]),
p('n1-232','Dismiss something as too small to count as a category.','N + のうちに入らない; V plain + うちに入らない','neutral/critical','Often downplays an amount of work, difficulty, or experience.','It excludes by a standard, not by physical entry.',[
['この程度の雨は雨の[うちに入らない]。','Rain this light hardly counts as rain.','A low degree is dismissed.'],['一度読んだだけでは勉強した[うちに入らない]。','Reading it once hardly counts as studying.','An effort does not meet a standard.'],['皿を一枚洗っただけでは手伝いの[うちに入らない]。','Washing one plate hardly counts as helping.','A minimal contribution is rejected.']]),
p('n1-233','Color a statement with personal feeling or informal emphasis.','Plain / polite clause + わ','colloquial; gender and regional variation','Intonation and dialect affect its tone; it is not universally feminine.','Do not assume a single social meaning for every speaker and region.',[
['この景色、本当にきれいだ[わ]。','This view really is beautiful.','A soft personal impression.'],['もうこんな時間だ[わ]。','Oh, it is this late already.','A spontaneous realization.'],['それなら私も行く[わ]。','In that case, I will come too.','An informal personal decision.']]),
p('n1-234','Set aside how a factor is judged while maintaining another point.','N + はどうであれ','neutral/formal','Often with 結果, 理由, or 評価.','It does not say the factor is unknown; it says it will not alter the conclusion.',[
['結果[はどうであれ]、挑戦したことに意味がある。','Whatever the result, trying has value.','The effort is valued independently.'],['理由[はどうであれ]、説明は必要だ。','Whatever the reason, an explanation is needed.','A duty remains.'],['周囲の評価[はどうであれ]、私は続ける。','Whatever others think, I will continue.','A decision is independent of judgment.']]),
p('n1-235','Show that even a basic threshold is unmet, let alone a greater one.','Greater item + はおろか + lesser item + も / さえ + negative','emphatic','The second item is normally easier or more basic.','Keep the scale in order so the let-alone contrast makes sense.',[
['漢字[はおろか]、ひらがなもまだ読めない。','I cannot read hiragana yet, let alone kanji.','The simpler script is not mastered.'],['旅行[はおろか]、外食する余裕もない。','I cannot afford to eat out, let alone travel.','A smaller expense is already impossible.'],['一時間[はおろか]、十分も待てない。','I cannot wait ten minutes, let alone an hour.','The lower time threshold fails.',{'十分':'じゅっぷん'}]]),
p('n1-236','Temporarily put a topic aside to focus on another.','N + はさておき; question clause + はさておき','neutral/formal','Often shifts from evaluation to a more immediate matter.','It postpones consideration, rather than proving the topic irrelevant forever.',[
['冗談[はさておき]、日程を決めよう。','Joking aside, let’s decide the schedule.','Returns to practical business.'],['値段[はさておき]、使いやすさを比べたい。','Putting price aside, I want to compare ease of use.','Temporarily isolates one criterion.'],['勝てるかどうか[はさておき]、参加してみよう。','Leaving aside whether we can win, let’s take part.','The uncertain result is not the present focus.']]),
p('n1-237','Describe neglecting something while concentrating elsewhere.','N + は / を + そっちのけで','colloquial/critical','Often refers to work, a duty, or another person being ignored.','It is stronger than simply doing two things at different times.',[
['宿題[はそっちのけで]ゲームをしていた。','He ignored his homework and played games.','A duty is displaced by pleasure.'],['客[をそっちのけで]店員同士が話していた。','The staff chatted among themselves, ignoring the customers.','People are improperly neglected.'],['食事[もそっちのけで]模型を作った。','I worked on the model, even neglecting meals.','Absorption overrides basic needs.']]),
p('n1-238','Pile up two causes of an overwhelming situation.','Plain clause + わ … + わで + result','colloquial/emphatic','Often lists troubles or surprises; multiple causes reinforce the result.','This paired listing differs from the single sentence-ending わ.',[
['雨は降る[わ]、風は強い[わで]、散歩どころではなかった。','It was raining and windy, so a walk was out of the question.','Bad conditions pile up.'],['鍵はない[わ]、携帯の電池は切れる[わで]、困り果てた。','My key was missing and my phone died, leaving me at a loss.','Two mishaps create a crisis.'],['子供は泣く[わ]、犬は吠える[わで]、眠れなかった。','The child cried and the dog barked, so I could not sleep.','Noisy causes accumulate.']]),
p('n1-239','Narrate something happening the instant another event occurs.','V dictionary + や否や','literary/narrative','Usually reports observed past events.','It is not the whether-or-not construction か否か.',[
['鐘が鳴る[や否や]鳥が飛び立った。','The instant the bell rang, the birds took flight.','An immediate reaction.'],['彼は封を切る[や否や]手紙を読み始めた。','He began reading the letter the moment he opened it.','Rapid consecutive actions.'],['雨がやむ[や否や]子供たちは外へ出た。','The children went outside as soon as the rain stopped.','A condition immediately releases action.']]),
p('n1-240','Deny an action emphatically, often with irritation.','Vます stem + やしない; Vている → Vていやしない','colloquial/rough','Often contrasts what should happen with what never happens.','This is an emphatic negative, not the suffix やすい.',[
['何度呼んでも返事をし[やしない]。','No matter how often I call, he never answers.','Irritation at an absent response.'],['そんな話、信じ[やしない]。','I will never believe a story like that.','A forceful denial.'],['この時計は正確に動き[やしない]。','This clock never runs accurately.','A complaint about repeated failure.']]),
p('n1-241','List demands or topics with a sense that there are too many.','やれ + item / clause + やれ + item / clause','colloquial/complaining','Often reports other people’s demands or a hectic assortment.','The repeated やれ is a listing device, not an instruction to do something.',[
['[やれ]会議だ、[やれ]出張だと、落ち着かない。','It is meetings, business trips, one thing after another; I cannot settle down.','An exhausting list of obligations.'],['[やれ]安くしろ、[やれ]早くしろと注文が多い。','They keep demanding that it be cheaper, faster, and so on.','Complains about multiple demands.'],['[やれ]暑い、[やれ]寒いと彼は文句ばかり言う。','He is forever complaining that it is too hot, too cold, and so on.','Reports an irritating variety of complaints.']]),
p('n1-242','Insist that an outcome stays the same despite any condition.','V volitional + が / と; い-adjective stem + かろうが; N + だろうと','emphatic/formal','Often paired with question words such as 誰 or 何.','The volitional form is concessive here, not an invitation.',[
['誰が反対し[ようと]私は続ける。','Whoever opposes it, I will continue.','Resolve survives opposition.'],['どれほど遠[かろうが]会いに行く。','However far away it is, I will go to see them.','Distance does not alter intention.'],['結果がどうであ[ろうと]報告してください。','Please report the result, whatever it may be.','The duty is independent of the outcome.']]),
p('n1-243','Apply a conclusion across two alternative conditions.','V volitional + が … V volitional + が; V volitional + と … V volitional + と','emphatic','The alternatives do not affect the main statement.','Unlike とも～とも, this affirms a stable conclusion rather than withholding judgment.',[
['雨が降ろ[うが]雪が降ろ[うが]配達する。','We deliver whether it rains or snows.','Either weather condition is accepted.'],['賛成されよ[うと]反対されよ[うと]、説明は尽くす。','Whether people agree or oppose it, I will explain fully.','Either reception leaves a commitment unchanged.'],['勝と[うが]負けよ[うが]、最後まで走る。','Win or lose, I will run to the end.','The outcome does not change the effort.']]),
p('n1-244','Make an evaluation depend on how something is done or viewed.','Vます stem + ようによっては / ようでは','neutral/formal','Often with 見る, 考える, 使う, or 言う.','よう here means manner; it is not the volitional ending.',[
['見[ようによっては]雲が鳥に見える。','Depending on how you look at it, the cloud looks like a bird.','Perspective affects an interpretation.'],['使い[ようによっては]古い箱も役に立つ。','Depending on how it is used, even an old box can be useful.','Method changes usefulness.'],['言い[ようでは]同じ内容も失礼に聞こえる。','Depending on how it is phrased, the same content can sound rude.','Wording affects social impact.']]),
p('n1-245','Describe an intended action blocked by circumstances.','V volitional + にも + same / related V potential negative','neutral','A practical obstacle prevents even attempting or completing the desired action.','The second clause must explain inability, not simply unwillingness.',[
['鍵がなくて帰ろ[うにも]帰れ[ない]。','Without my key, I cannot go home even though I want to.','A missing item blocks intention.'],['名前を知らず、探そ[うにも]探せ[ない]。','I do not know the name, so I cannot search even if I want to.','Essential information is missing.'],['痛くて立と[うにも]立て[ない]。','It hurts so much that I cannot stand up even though I try.','A physical condition prevents action.']]),
p('n1-246','State that doing or not doing something makes no difference.','V volitional + と … V dictionary + まいと; V volitional + が … まいが','formal/emphatic','For する, すまい and するまい occur; ichidan may use stem + まい.','The two clauses concern the positive and negative of the same action.',[
['参加しよ[うと]参加する[まいと]会費は同じだ。','The fee is the same whether you participate or not.','Attendance does not alter a rule.'],['彼が来よ[うが]来る[まいが]予定どおり始める。','We will start as planned whether he comes or not.','A plan is independent of one person.'],['信じよ[うと]信じる[まいと]、これは事実だ。','Whether you believe it or not, this is a fact.','Belief does not change a claim.']]),
p('n1-247','State a reason in a formal or literary style.','Plain clause + ゆえに; N +（の）ゆえに; な-adjective + な / である + ゆえに','formal/literary','Often used in reasoning or solemn explanation.','It gives a cause; it is not the goal use of ために.',[
['経験が浅い[ゆえに]判断を誤った。','I misjudged it because of my limited experience.','A cause explains a failure.'],['若さ[ゆえに]無理をしてしまった。','I pushed myself too hard because I was young.','A personal quality explains behavior.'],['希少である[ゆえに]保護が必要だ。','It needs protection because it is rare.','A formal causal argument.']]),
p('n1-248','Give a statement or invitation a forceful familiar tone.','Plain clause + ぞ / ぜ','rough/familiar','Often associated with masculine speech, but use depends on persona and context.','Avoid these endings in respectful or formal exchanges.',[
['忘れ物がないか確かめる[ぞ]。','We are checking that nothing is left behind.','A firm announcement to a familiar group.'],['もうすぐ着く[ぞ]。','We will be there very soon.','An emphatic familiar notice.'],['一緒に行こう[ぜ]。','Let’s go together.','A familiar energetic invitation.']]),
p('n1-249','Say that an intended action remained undone at the end.','Vない stem + ずじまい; する → せずじまい','neutral/regretful','Usually looks back on a missed opportunity.','It is an unrealized action, not an action completed badly.',[
['忙しくて映画を見[ずじまい]だった。','I was busy and never got around to seeing the film.','An intended leisure activity remains undone.'],['結局、お礼も言わ[ずじまい]になった。','In the end, I never got to say thank you.','A social opportunity is lost.'],['旅行中は一度も泳が[ずじまい]だった。','I ended up not swimming once during the trip.','A hoped-for activity never happens.']]),
p('n1-250','Predict a compelling effect or declare an action will certainly be taken.','Vない stem + ずにはおかない; Vない + ではおかない; する → せず','formal/emphatic','Can describe an inevitable emotional effect or strong determination.','Unlike ずには済まない, it stresses a compelling force rather than social obligation.',[
['この物語は読む人を感動させ[ずにはおかない]。','This story is bound to move its readers.','The work has a compelling effect.'],['真相を明らかにせ[ずにはおかない]。','I will not rest until I uncover the truth.','A determined declaration.'],['その発見は議論を呼ば[ずにはおかない]だろう。','That discovery is bound to provoke debate.','An effect is judged unavoidable.']]),
p('n1-251','Say that responsibility or circumstances require an action.','Vない stem + ずには済まない; Vない + では済まない; する → せず','neutral/formal','The action is needed to settle a social or practical obligation.','This concerns necessity, rather than the spontaneous impulse of ずにはいられない.',[
['迷惑をかけた以上、謝ら[ずには済まない]。','Having caused trouble, I must apologize.','Responsibility creates an obligation.'],['契約を破れば賠償せ[ずには済まない]。','If we break the contract, we cannot avoid paying compensation.','An unavoidable consequence.'],['不備が見つかり、説明し[ないでは済まなかった]。','Once the defects were found, we had to give an explanation.','A duty follows discovery.']]),
p('n1-252','Say that something is possible or true without an expected action.','Vない stem + ずとも; する → せずとも','literary/formal','Often expresses that a step is unnecessary.','For ichidan, remove ない; for godan use the negative stem.',[
['全部読ま[ずとも]要点は分かる。','You can grasp the main point without reading it all.','Complete reading is unnecessary.'],['言わ[ずとも]気持ちは伝わった。','The feeling came across without words.','Communication needs no spoken statement.'],['急が[ずとも]十分間に合う。','There is plenty of time even without hurrying.','No need for an extra effort.']]),
p('n1-253','Describe a situation filled entirely with one kind of thing.','N + ずくめ','neutral/emphatic','Common with positive events and fixed combinations such as 黒ずくめ.','Unlike まみれ, it need not describe physical dirt; combinations are limited.',[
['今日はいいこと[ずくめ]の一日だった。','Today was a day full of good things.','A positive run of events.'],['黒[ずくめ]の服を着た人が来た。','Someone dressed entirely in black arrived.','A fixed color combination.'],['この提案は利点[ずくめ]に見える。','This proposal seems to have nothing but advantages.','One category fills an evaluation.']]),
];
